/* eslint-disable no-console */
import autocannon from "autocannon";

const BASE_URL = process.env.LOAD_TARGET_URL || "http://localhost:3001";
const duration = Number(process.env.LOAD_DURATION || "15");

function requestFactory() {
  const traceId = `flow-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  return [
    {
      method: "POST",
      path: "/api/agent/plan",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ prompt: "周六带娃去哪玩，亲子活动", traceId }),
    },
    {
      method: "GET",
      path: "/api/health",
      headers: {},
      body: undefined,
    },
  ];
}

const setupClient = (_client) => {
  const requests = requestFactory();
  return { requests };
};

const instance = autocannon({
  url: BASE_URL,
  duration,
  connections: 10,
  amount: 100,
  pipelining: 2,
  requests: requestFactory(),
});

autocannon.track(instance, { renderProgressBar: true });

instance.on("done", (result) => {
  console.log(`\n--- Flow Load Test Done ---`);
  console.log(`Requests:  ${result.requests.total}`);
  console.log(`Latency avg:${result.latency.average}ms  p99:${result.latency.p99}ms`);
  console.log(`Errors:    ${result.errors}`);
  console.log(`Timeouts:  ${result.timeouts}`);
});

process.once("SIGINT", () => instance.stop());

/* eslint-disable no-console */
import autocannon from "autocannon";
import { parseArgs } from "node:util";

const BASE_URL = process.env.LOAD_TARGET_URL || "http://localhost:3001";

const { values } = parseArgs({
  options: {
    path: { type: "string", default: "/api/agent/plan" },
    method: { type: "string", default: "POST" },
    duration: { type: "string", default: "10" },
    connections: { type: "string", default: "10" },
  },
  strict: false,
});

const url = `${BASE_URL}${values.path}`;
const duration = Number(values.duration);
const connections = Number(values.connections);
const method = (values.method || "POST").toUpperCase();

const instance = autocannon({
  url,
  method,
  connections,
  duration,
  headers: { "content-type": "application/json" },
  ...(method === "POST"
    ? {
        body: JSON.stringify({
          prompt: "周六带娃去哪玩，亲子活动",
          traceId: `load-${Date.now()}`,
        }),
      }
    : {}),
});

autocannon.track(instance, { renderProgressBar: true });

instance.on("done", (result) => {
  console.log(`\n--- Load Test Done: ${result.title || url} ---`);
  console.log(`Requests:  ${result.requests.total}`);
  console.log(`Throughput:${result.throughput.total} bytes`);
  console.log(`Latency avg:${result.latency.average}ms  p99:${result.latency.p99}ms`);
  console.log(`Errors:    ${result.errors}`);
  console.log(`Timeouts:  ${result.timeouts}`);
});

process.once("SIGINT", () => instance.stop());

import { useState, useEffect, useCallback, useRef } from "react";
import { CheckCircle2, AlertCircle, Info, X } from "lucide-react";
import styles from "./GlassToast.module.scss";

export type ToastType = "success" | "error" | "info";

export interface ToastMessage {
  id: string;
  text: string;
  type: ToastType;
  duration?: number;
}

interface GlassToastProps {
  toast: ToastMessage | null;
  onDismiss: () => void;
}

const ICONS = {
  success: CheckCircle2,
  error: AlertCircle,
  info: Info,
} as const;

const ICON_CLASS = {
  success: styles.iconSuccess,
  error: styles.iconError,
  info: styles.iconInfo,
} as const;

const PROGRESS_CLASS = {
  success: styles.progressSuccess,
  error: styles.progressError,
  info: styles.progressInfo,
} as const;

export function GlassToast({ toast, onDismiss }: GlassToastProps) {
  const [exiting, setExiting] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  const dismiss = useCallback(() => {
    setExiting(true);
    setTimeout(onDismiss, 240);
  }, [onDismiss]);

  useEffect(() => {
    if (!toast) return;
    // Defer state reset outside the effect callback to satisfy lint rule
    const raf = requestAnimationFrame(() => setExiting(false));
    const duration = toast.duration ?? 2800;
    timerRef.current = setTimeout(dismiss, duration);
    return () => {
      cancelAnimationFrame(raf);
      clearTimeout(timerRef.current);
    };
  }, [toast, dismiss]);

  if (!toast) return null;

  const Icon = ICONS[toast.type];

  return (
    <div className={styles.overlay} role="status" aria-live="polite">
      <div className={`${styles.card} ${exiting ? styles.cardExit : ""}`}>
        <span className={`${styles.icon} ${ICON_CLASS[toast.type]}`}>
          <Icon size={16} />
        </span>
        <span className={styles.text}>{toast.text}</span>
        <button
          type="button"
          className={styles.close}
          aria-label="关闭"
          onClick={dismiss}
        >
          <X size={14} />
        </button>
        <div className={styles.progress}>
          <div
            className={`${styles.progressBar} ${PROGRESS_CLASS[toast.type]}`}
            style={{ animationDuration: `${toast.duration ?? 2800}ms` }}
          />
        </div>
      </div>
    </div>
  );
}

/** 便捷 hook：返回 [currentToast, showToast] */
let _toastId = 0;
export function useGlassToast() {
  const [toast, setToast] = useState<ToastMessage | null>(null);
  const timerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  const show = useCallback((text: string, type: ToastType = "success", duration?: number) => {
    clearTimeout(timerRef.current);
    const id = String(++_toastId);
    setToast({ id, text, type, duration });
  }, []);

  const dismiss = useCallback(() => {
    setToast(null);
  }, []);

  return { toast, show, dismiss } as const;
}

import { Menu, X, MapPin, Navigation, AlertCircle } from "lucide-react";
import { useState } from "react";
import { navItems } from "../data/navigation";
import type { ModalKey, NavKey, SessionUser } from "../types";
import { Button } from "./Button";
import { Modal } from "./Modal";
import styles from "./NavBar.module.scss";

interface NavBarProps {
  active: NavKey;
  onNavigate: (key: NavKey) => void;
  onOpenModal: (key: ModalKey) => void;
  user: SessionUser | null;
  onLogout: () => void;
  onRequestLocation?: () => void;
}

export function NavBar({ active, onNavigate, onOpenModal, user, onLogout, onRequestLocation }: NavBarProps) {
  const [open, setOpen] = useState(false);
  const [showLocationError, setShowLocationError] = useState(false);

  const handleNavigate = (key: NavKey) => {
    if (key === "developers") {
      onOpenModal("developerComingSoon");
      setOpen(false);
      return;
    }
    onNavigate(key);
    setOpen(false);
  };

  const locationLabel = user?.locationLabel || user?.city || "";
  const isLocationError = locationLabel.includes("不可用") || locationLabel.includes("失败");

  const handleLocationClick = () => {
    if (isLocationError) {
      setShowLocationError(true);
    } else {
      onRequestLocation?.();
    }
  };

  return (
    <>
      <nav className={styles.nav} aria-label="主导航">
        <button className={styles.brand} type="button" onClick={() => handleNavigate("home")}>
          <span className={styles.brandDot} aria-hidden="true" />
          <span>周末有谱</span>
        </button>
        <div className={styles.links}>
          {navItems.map((item) => (
            <button
              className={`${styles.link} ${active === item.key ? styles.active : ""}`}
              type="button"
              key={item.key}
              aria-current={active === item.key ? "page" : undefined}
              onClick={() => handleNavigate(item.key)}
            >
              {item.label}
            </button>
          ))}
        </div>
        <div className={styles.actions}>
          {/* 定位 pill */}
          {user && locationLabel ? (
            <button
              type="button"
              className={styles.locationPill}
              onClick={handleLocationClick}
              title={isLocationError ? "查看定位失败原因" : "点击重新定位"}
            >
              <MapPin size={14} />
              <span>{locationLabel}</span>
            </button>
          ) : user && onRequestLocation ? (
            <button
              type="button"
              className={styles.locationPillMuted}
              onClick={onRequestLocation}
              title="开启定位"
            >
              <Navigation size={14} />
              <span>定位</span>
            </button>
          ) : null}

          {user ? (
            <>
              <button className={styles.userBadge} type="button" onClick={() => handleNavigate("profile")}>
                {user.mode === "guest" ? "游客" : user.name}
              </button>
              <Button variant="dark" size="small" onClick={onLogout}>退出</Button>
            </>
          ) : (
            <>
              <button className={styles.loginLink} type="button" onClick={() => onOpenModal("login")}>登录</button>
              <Button size="small" onClick={() => onOpenModal("register")}>免费注册</Button>
            </>
          )}
        </div>
        <button
          className={styles.menuButton}
          type="button"
          aria-label={open ? "关闭菜单" : "打开菜单"}
          onClick={() => setOpen((value) => !value)}
        >
          {open ? <X size={20} /> : <Menu size={20} />}
        </button>
      </nav>
      <div className={styles.mobilePanel} hidden={!open}>
        {navItems.map((item) => (
          <button
            className={`${styles.link} ${active === item.key ? styles.active : ""}`}
            type="button"
            key={item.key}
            onClick={() => handleNavigate(item.key)}
          >
            {item.label}
          </button>
        ))}

        {user && locationLabel ? (
          <button
            type="button"
            className={styles.mobileLocationPill}
            onClick={() => {
              if (isLocationError) {
                setShowLocationError(true);
              } else {
                onRequestLocation?.();
              }
              setOpen(false);
            }}
          >
            <MapPin size={14} />
            <span>{locationLabel}</span>
          </button>
        ) : null}

        <div className={styles.mobileActions}>
          {user ? (
            <>
              <Button variant="ghost" size="small" onClick={() => handleNavigate("profile")}>{user.mode === "guest" ? "游客" : user.name}</Button>
              <Button variant="dark" size="small" onClick={onLogout}>退出</Button>
            </>
          ) : (
            <>
              <Button variant="ghost" size="small" onClick={() => onOpenModal("login")}>登录</Button>
              <Button size="small" onClick={() => onOpenModal("register")}>免费注册</Button>
            </>
          )}
        </div>
      </div>

      {/* Location error modal */}
      {showLocationError && (
        <Modal
          modal="locationError"
          onClose={() => setShowLocationError(false)}
          onPrimary={() => {
            setShowLocationError(false);
            onRequestLocation?.();
          }}
          onSecondary={() => {
            setShowLocationError(false);
            onOpenModal("location");
          }}
        />
      )}
    </>
  );
}

