// ── Profile: 人物画像 ──

export async function getProfileBundle(): Promise<ProfileBundle> {
  return apiJson<ProfileBundle>("/api/profile/me");
}

export async function updateProfile(input: { displayName?: string; city?: string; startPoint?: string }) {
