                {/* 危险操作 */}
                <div
                  className={`${s.securitySection} ${s.dangerZone}`}
                >
                  <h4>危险操作</h4>
                  <div
                    style={{
                      display: "flex",
                      gap: 10,
                      flexWrap: "wrap",
