/**
 * Agent Runtime input
 */
export interface AgentRunInput {
  userId?: string;
  guestId?: string;
  conversationId?: string;
  prompt: string;
  city?: string;
  lat?: number;
  lng?: number;
  modelMode: "flash" | "pro";
  planningMode?: "mock" | "hybrid" | "llm";
  device: "desktop" | "mobile";
  source: "home" | "feature" | "qr_handoff" | "api";
  permissions?: UserPermissionSnapshot;
}

/**
 * Agent Runtime result
 */
export interface AgentRunResult {
  traceId: string;
  conversationId: string;
  userMessageId: string;
  assistantMessageId: string;
  intent: UserIntent;
  cityContext: CityContext;
  toolSummary: {
    totalCalls: number;
    totalLatencyMs: number;
    successfulCalls: number;
    failedCalls: number;
    toolsUsed: string[];
    errors: Array<{ tool: string; error: string }>;
  };
  options: ActivityPlan[];
  executableActions: ExecutionAction[];
  autoExecutedActions: ExecutionAction[];
  blockedActions: ExecutionAction[];
  validation: any;
  nextActions: string[];
  modelMode: string;
  llmModel: string;
}

/**
 * Agent Runtime - orchestrates the entire planning pipeline with tool integration
 */
export async function runAgentRuntime(input: AgentRunInput): Promise<AgentRunResult> {
  const traceId = createTraceId();
  const planId = createId("plan");
  const conversationId = input.conversationId || createId("conv");
  const userMessageId = createId("msg");
  const assistantMessageId = createId("msg");
  const mode = input.planningMode ?? env.PLANNING_MODE;
  const modelMode = input.modelMode ?? "flash";

  // Select LLM model based on mode
  const llmModel =
    modelMode === "pro"
      ? (env.LLM_PRO_MODEL ?? env.LLM_MODEL)
      : (env.LLM_FLASH_MODEL ?? env.LLM_MODEL);

  // 1. Build city context
  const cityContext = buildCityContext({
    manualCity: input.city,
    browserLat: input.lat,
    browserLng: input.lng,
    profileCity: undefined, // Would load from DB in production
    conversationCity: undefined, // Would load from conversation in production
    fallbackCity: undefined, // Don't default to Beijing
  });

  // 2. Parse intent
  const planningRequest: PlanningRequest = {
    prompt: input.prompt,
    city: cityContext.city || undefined,
    startPoint: undefined,
    budget: undefined,
    departAt: undefined,
    companions: undefined,
  };

  const intent = await extractIntent(planningRequest);

  // 3. Build planning context
  const context = await buildPlanningContext({ traceId, planId, intent });

  // 4. Create tool executor
  const executor = createToolExecutor(modelMode);

  // 5. Execute tools in parallel batches if not in mock mode
  let toolSummary: {
    totalCalls: number;
    totalLatencyMs: number;
    successfulCalls: number;
    failedCalls: number;
    toolsUsed: string[];
    errors: Array<{ tool: string; error: string }>;
  } = {
    totalCalls: 0,
    totalLatencyMs: 0,
    successfulCalls: 0,
    failedCalls: 0,
    toolsUsed: [],
    errors: [],
  };

  if (mode !== "mock" && cityContext.city) {
    const toolCtx: ToolExecutionContext = {
      traceId,
      userId: input.userId,
      guestId: input.guestId,
      city: cityContext.city,
      adcode: cityContext.adcode,
      lat: input.lat,
      lng: input.lng,
    };

    // Batch 1: Context discovery (weather, POI search)
    try {
      const batch1 = await executor.runBatch({
        batchName: "context_discovery",
        parallel: true,
        maxConcurrency: 5,
        tools: [
          {
            tool: "amap.weatherLive",
            input: { city: cityContext.city },
            reason: "Get current weather",
          },
          {
            tool: "amap.weatherForecast",
            input: { city: cityContext.city },
            reason: "Get weather forecast",
          },
          {
            tool: "amap.searchPoiText",
            input: {
              keywords: intent.participantMode === "family" ? "亲子 展览 室内" : "展览 活动",
              city: cityContext.city,
              citylimit: true,
              offset: 10,
            },
            reason: "Search for activities",
          },
          {
            tool: "amap.searchPoiText",
            input: {
              keywords: "轻食 餐厅",
              city: cityContext.city,
              citylimit: true,
              offset: 10,
            },
            reason: "Search for restaurants",
          },
        ],
        ctx: toolCtx,
      });

      toolSummary = executor.getSummary(batch1.results);
    } catch (error) {
      // Tool failures should not crash the pipeline
      console.error("Tool execution failed:", error);
      toolSummary.errors.push({
        tool: "batch",
        error: error instanceof Error ? error.message : String(error),
      } as { tool: string; error: string });
    }
  }

  // 6. Generate candidates (with mock fallback if tools failed)
  const candidates = await generateCandidates(context);

  // 7. Rank candidates
  const ranked = rankCandidates(intent, candidates);

  // 8. Generate plans
  let options;
  if (mode === "llm") {
    options = await generateLlmPlans({ traceId, planId, intent, context, candidates: ranked });
  } else if (mode === "hybrid") {
    try {
      options = await generateLlmPlans({ traceId, planId, intent, context, candidates: ranked });
    } catch {
      options = generateMockPlans({ traceId, planId, intent, context, candidates: ranked });
    }
  } else {
    options = generateMockPlans({ traceId, planId, intent, context, candidates: ranked });
  }

  // 9. Validate plans
  const validation = validatePlans({ intent, candidates: ranked, options });

  // 10. Generate executable actions
  const executableActions = createActionsForPlans({ planId, options, intent });

  // 11. Filter actions by permissions
  const permissions = input.permissions || {
    locationEnabled: true,
    memoryEnabled: true,
    calendarEnabled: false,
    shareEnabled: true,
    developerEnabled: false,
    grantedScopes: [],
  };

  const { allowed, blocked } = filterActionsByPermissions(executableActions, permissions);

  // 12. Auto-execute allowed actions (if enabled)
  const autoExecutedActions: ExecutionAction[] = [];
  if (env.AUTO_EXECUTION_ENABLED) {
    // In production, this would actually execute the actions
    // For now, just mark them as prepared
    for (const action of allowed.slice(0, env.AUTO_EXECUTION_MAX_ACTIONS)) {
      if (action.type === "navigation") {
        // Navigation can be auto-executed
        autoExecutedActions.push({ ...action, status: "success" as any });
      }
    }
  }

  // 13. Validate output city safety
  if (cityContext.city) {
    for (const option of options) {
      const summaryText = `${option.title} ${option.summary} ${option.timeline.map((t) => t.title).join(" ")}`;
      // Simple city validation - in production use proper NLP
      const cityPattern = /(北京|上海|天津|重庆|广州|深圳|杭州|南京|苏州|成都|武汉|西安|郑州|青岛|大连|厦门|长沙|哈尔滨|沈阳|济南|昆明|贵阳|兰州|南昌|福州|合肥|海口|石家庄|太原|长春|南宁|呼和浩特|银川|西宁|乌鲁木齐|拉萨|无锡|常州|南通|宁波|温州|嘉兴|绍兴|金华|台州|湖州|衢州|丽水|舟山)/g;
      const matches = summaryText.match(cityPattern);
      if (matches && !matches.includes(cityContext.city)) {
        console.warn(`Output city safety check failed: found cities ${matches.join(", ")} but expected ${cityContext.city}`);
      }
    }
  }

  // 14. Return result
  return {
    traceId,
    conversationId,
    userMessageId,
    assistantMessageId,
    intent,
    cityContext,
    toolSummary,
    options,
    executableActions,
    autoExecutedActions,
    blockedActions: blocked,
    validation,
    nextActions: ["选择方案", "查看风险", "确认预约", "写入日历", "分享给同行人"],
    modelMode,
    llmModel,
  };
}

import { createId, createIdempotencyKey } from "../../common/id";
import type { ExecutionAction } from "../planning/schemas";
import { transitionState, type ActionStatus } from "./stateMachine";
import type { PermissionScope, UserPermissionSnapshot } from "../agent/middleware/permissionGuard";

// Use a lazy-loaded Prisma client to avoid initialization issues
let prismaInstance: any = null;

function getPrisma() {
  if (!prismaInstance) {
    try {
      const { PrismaClient } = require("../../generated/prisma/client.js");
      prismaInstance = new PrismaClient();
    } catch (error) {
      console.warn("Prisma client not available, using mock implementation");
      prismaInstance = createMockPrisma();
    }
  }
  return prismaInstance;
}

function createMockPrisma() {
  return {
    action: {
      findUnique: async () => null,
      create: async (data: any) => ({ id: createId("act"), ...data.data }),
      update: async () => ({ id: "mock" }),
    },
    actionEvent: {
      create: async () => ({ id: "mock" }),
    },
  };
}

/**
 * Action execution result
 */
export interface ActionResult {
  actionId: string;
  status: ActionStatus;
  result?: unknown;
  error?: string;
}

/**
 * Action executor - handles execution of actions with idempotency and permissions
 */
export class ActionExecutor {
  /**
   * Execute an action with idempotency check
   */
  async executeAction(params: {
    userId?: string;
    planId: string;
    action: ExecutionAction;
    permissions: UserPermissionSnapshot;
  }): Promise<ActionResult> {
    const { userId, planId, action, permissions } = params;
    const prisma = getPrisma();

    // Check if action already exists (idempotency)
    const existing = await prisma.action.findUnique({
      where: { idempotencyKey: action.idempotencyKey },
    });

    if (existing) {
      return {
        actionId: existing.id,
        status: existing.status as ActionStatus,
        result: existing.result as any,
        error: existing.errorMessage || undefined,
      };
    }

    // Create action record
    const actionRecord = await prisma.action.create({
      data: {
        userId: userId || "guest",
        planId,
        type: action.type,
        status: "proposed",
        confirmationRequired: action.confirmationRequired,
        idempotencyKey: action.idempotencyKey,
        payload: action.payload as any,
        quote: action.priceEstimate ? { price: action.priceEstimate } : undefined,
      },
    });

    // Transition to prepared
    const status = transitionState("proposed", "prepared");
    await prisma.action.update({
      where: { id: actionRecord.id },
      data: { status },
    });

    // Check if authorization is required
    if (action.confirmationRequired) {
      const newStatus = transitionState(status, "waiting_authorization");
      await prisma.action.update({
        where: { id: actionRecord.id },
        data: { status: newStatus },
      });

      return {
        actionId: actionRecord.id,
        status: newStatus,
      };
    }

    // Execute action
    return await this.performExecution(actionRecord.id, action.type, action.payload);
  }

  /**
   * Perform the actual execution of an action
   */
  private async performExecution(
    actionId: string,
    type: string,
    payload: unknown,
  ): Promise<ActionResult> {
    const prisma = getPrisma();

    // Update status to executing
    await prisma.action.update({
      where: { id: actionId },
      data: { status: "executing" },
    });

    try {
      // Execute based on action type
      let result: unknown;
      switch (type) {
        case "navigation":
          result = await this.executeNavigation(payload);
          break;
        case "calendar_event":
          result = await this.executeCalendar(payload);
          break;
        case "share_message":
          result = await this.executeShare(payload);
          break;
        case "restaurant_reservation":
        case "ticket_lock":
          result = await this.executeReservation(payload);
          break;
        default:
          throw new Error(`Unknown action type: ${type}`);
      }

      // Update status to succeeded
      await prisma.action.update({
        where: { id: actionId },
        data: {
          status: "succeeded",
          result: result as any,
        },
      });

      // Log action event
      await prisma.actionEvent.create({
        data: {
          actionId,
          eventType: "execution_success",
          fromStatus: "executing",
          toStatus: "succeeded",
          payload: result as any,
        },
      });

      return {
        actionId,
        status: "succeeded",
        result,
      };
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);

      // Update status to failed
      await prisma.action.update({
        where: { id: actionId },
        data: {
          status: "failed",
          errorMessage,
        },
      });

      // Log action event
      await prisma.actionEvent.create({
        data: {
          actionId,
          eventType: "execution_failed",
          fromStatus: "executing",
          toStatus: "failed",
          payload: { error: errorMessage },
        },
      });

      return {
        actionId,
        status: "failed",
        error: errorMessage,
      };
    }
  }

  /**
   * Authorize an action for execution
   */
  async authorizeAction(actionId: string): Promise<ActionResult> {
    const prisma = getPrisma();

    const action = await prisma.action.findUnique({
      where: { id: actionId },
    });

    if (!action) {
      throw new Error("Action not found");
    }

    if (action.status !== "waiting_authorization") {
      throw new Error(`Action is not waiting for authorization: ${action.status}`);
    }

    // Transition to authorized
    const newStatus = transitionState(action.status as ActionStatus, "authorized");
    await prisma.action.update({
      where: { id: actionId },
      data: { status: newStatus },
    });

    // Log authorization event
    await prisma.actionEvent.create({
      data: {
        actionId,
        eventType: "authorized",
        fromStatus: "waiting_authorization",
        toStatus: "authorized",
      },
    });

    // Execute the action
    return await this.performExecution(actionId, action.type, action.payload);
  }

  /**
   * Execute navigation action
   */
  private async executeNavigation(payload: unknown): Promise<unknown> {
    // In production, this would generate a real navigation link
    return {
      navigationUrl: "https://uri.amap.com/navigation",
      points: (payload as any).points,
    };
  }

  /**
   * Execute calendar action
   */
  private async executeCalendar(payload: unknown): Promise<unknown> {
    // In production, this would write to user's calendar
    return {
      calendarEventId: `cal_${Date.now()}`,
      title: (payload as any).title,
      startTime: (payload as any).startTime,
      endTime: (payload as any).endTime,
    };
  }

  /**
   * Execute share action
   */
  private async executeShare(payload: unknown): Promise<unknown> {
    // In production, this would generate a shareable link
    return {
      shareUrl: `https://your-domain.com/share/${Date.now()}`,
      text: (payload as any).text,
    };
  }

  /**
   * Execute reservation action
   */
  private async executeReservation(payload: unknown): Promise<unknown> {
    // In production, this would call external reservation APIs
    return {
      reservationId: `res_${Date.now()}`,
      poiId: (payload as any).poiId,
      poiName: (payload as any).poiName,
      status: "confirmed",
    };
  }
}

