/**
 * Create or update a device session
 */
export async function upsertDeviceSession(params: {
  userId?: string;
  guestId?: string;
  deviceType: string;
  platform: string;
  userAgent: string;
  city?: string;
  lat?: number;
  lng?: number;
}): Promise<{ sessionId: string }> {
  const prisma = getPrisma();

  // Try to find existing session for this user/guest
  const existing = await prisma.deviceSession.findFirst({
    where: {
      OR: [
        { userId: params.userId },
        { guestId: params.guestId },
      ],
    },
  });

  if (existing) {
    // Update existing session
    await prisma.deviceSession.update({
      where: { id: existing.id },
      data: {
        lastCity: params.city,
        lastLat: params.lat,
        lastLng: params.lng,
        lastSeenAt: new Date(),
      },
    });

    return { sessionId: existing.id };
  }

  // Create new session
  const session = await prisma.deviceSession.create({
    data: {
      userId: params.userId,
      guestId: params.guestId,
      deviceType: params.deviceType,
      platform: params.platform,
      userAgent: params.userAgent,
      lastCity: params.city,
      lastLat: params.lat,
      lastLng: params.lng,
      lastSeenAt: new Date(),
    },
  });

  return { sessionId: session.id };
}

/**
 * Get device session
 */
export async function getDeviceSession(sessionId: string): Promise<{
  userId?: string;
  guestId?: string;
  deviceType: string;
  platform: string;
  lastCity?: string;
  lastLat?: number;
  lastLng?: number;
} | null> {
  const prisma = getPrisma();

  const session = await prisma.deviceSession.findUnique({
    where: { id: sessionId },
  });

  if (!session) {
    return null;
  }

  return {
    userId: session.userId || undefined,
    guestId: session.guestId || undefined,
    deviceType: session.deviceType,
    platform: session.platform,
    lastCity: session.lastCity || undefined,
    lastLat: session.lastLat || undefined,
    lastLng: session.lastLng || undefined,
  };
}

