/**
 * Agent 路由 — /api/agent/*
 */

import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import type { PrismaClient } from "../../generated/prisma/client.js";
import { ZodError, z } from "zod";
import { parseDemand, planningRequestSchema, runPlanningAgent, simulateWhatIf } from "../services/agent.js";
import { runPlanningPipeline } from "../modules/agent/orchestrator.js";
import { saveActions } from "../services/store.js";
import * as mem from "../services/memoryStore.js";

export async function registerAgentRoutes(app: FastifyInstance) {
  // Global per-endpoint guard (kept lenient); strict model-based quota handled below.
  const planningRateLimit = {
    max: 100, // 100 requests per minute
    timeWindow: "1 minute",
    skipOnError: true,
  };

  const planningModeQuota = {
    flash: { max: 30, windowMs: 60 * 60 * 1000 },
    pro: { max: 100, windowMs: 60 * 60 * 1000 },
  } as const;
  const maxPlanningCounterEntries = 2000;
  const planningCounters = new Map<string, { count: number; resetAt: number }>();
  type PlanningModeBody = { modelMode?: "flash" | "pro" };

  const enforcePlanningQuota = (request: FastifyRequest<{ Body: PlanningModeBody }>, reply: FastifyReply): boolean => {
    if (planningCounters.size > maxPlanningCounterEntries) {
      const now = Date.now();
      for (const [k, v] of planningCounters.entries()) {
        if (v.resetAt <= now) planningCounters.delete(k);
      }
    }
    const modelMode = request?.body?.modelMode === "pro" ? "pro" : "flash";
    const quota = planningModeQuota[modelMode];
    const identity = request.userId ?? request.ip ?? "anonymous";
    const key = `${identity}:${modelMode}`;
    const now = Date.now();
    const current = planningCounters.get(key);
    if (!current || now >= current.resetAt) {
      planningCounters.set(key, { count: 1, resetAt: now + quota.windowMs });
      return true;
    }
    if (current.count >= quota.max) {
      const retryAfterSec = Math.max(1, Math.ceil((current.resetAt - now) / 1000));
      reply
        .status(429)
        .header("Retry-After", String(retryAfterSec))
        .send({ error: "RATE_LIMIT_EXCEEDED", message: `当前模型请求过于频繁，请 ${retryAfterSec} 秒后重试` });
      return false;
    }
    current.count += 1;
    planningCounters.set(key, current);
    return true;
  };

  app.post(
    "/api/agent/parse",
    {
      config: { rateLimit: planningRateLimit },
      preHandler: [app.optionalAuthGuard],
    },
    async (request, reply) => {
      try {
        const input = planningRequestSchema.parse(request.body);
        return parseDemand(input);
      } catch (error) {
        if (error instanceof ZodError)
          return reply.status(400).send({ error: "INVALID_REQUEST", issues: error.issues });
        throw error;
      }
    }
  );

  app.post(
    "/api/agent/plan",
    {
      config: { rateLimit: planningRateLimit },
      preHandler: [app.optionalAuthGuard, (request, reply, done) => {
        if (!enforcePlanningQuota(request as FastifyRequest<{ Body: PlanningModeBody }>, reply)) return;
        done();
      }],
    },
    async (request, reply) => {
    try {
      const input = planningRequestSchema.parse(request.body);
      const userId = (request as any).userId as string | undefined;
      const db: PrismaClient | null = app.db;

      // ── 1. 创建或获取会话 ──
      let conversationId = (request.body as any).conversationId as string | undefined;
      if (!conversationId) {
        if (db) {
          try {
            const conv = await db.conversation.create({
              data: {
                userId: userId ?? undefined,
                guestId: !userId ? ((request.body as any).guestId ?? null) : null,
                title: input.prompt.length > 30 ? input.prompt.slice(0, 30) + "…" : input.prompt,
                city: input.city ?? "北京",
                modelMode: (input as any).modelMode ?? "flash",
              },
            });
            conversationId = conv.id;
          } catch {
            // fallback
          }
        }
        if (!conversationId) {
          const conv = mem.createConversation({
            userId,
            guestId: !userId ? ((request.body as any).guestId ?? null) : null,
            title: input.prompt.length > 30 ? input.prompt.slice(0, 30) + "…" : input.prompt,
            city: input.city,
            modelMode: (input as any).modelMode,
          });
          conversationId = conv.id;
        }
      }

      // ── 2. 保存用户消息 ──
      if (db) {
        try {
          await db.message.create({
            data: { conversationId, role: "user", content: input.prompt },
          });
        } catch {
          mem.addMessage({ conversationId, role: "user", content: input.prompt });
        }
      } else {
        mem.addMessage({ conversationId, role: "user", content: input.prompt });
      }

      // ── 3. 运行规划管道 ──
      const result = await runPlanningPipeline({
        ...input,
        providers: app.providers ?? undefined,
        userId,
      });

      // ── 3.5 保存生成的 actions ──
      if (result.executableActions?.length) {
        saveActions(result.executableActions);
      }

      // ── 4. 保存助手消息 ──
      const assistantContent = result.summary || "为你找到以下方案：";
      if (db) {
        try {
          await db.message.create({
            data: {
              conversationId,
              role: "assistant",
              content: assistantContent,
              payloadJson: { type: "plan", data: { planId: result.planId, options: result.options, summary: result.summary } },
            },
          });
        } catch {
          mem.addMessage({ conversationId, role: "assistant", content: assistantContent });
        }
      } else {
        mem.addMessage({ conversationId, role: "assistant", content: assistantContent });
      }

      return { ...result, conversationId };
    } catch (error) {
      if (error instanceof ZodError) return reply.status(400).send({ error: "INVALID_REQUEST", issues: error.issues });
      throw error;
    }
  });

  // Streaming endpoint for planning
  app.post(
    "/api/agent/plan/stream",
    {
      config: { rateLimit: planningRateLimit },
      preHandler: [app.optionalAuthGuard, (request, reply, done) => {
        if (!enforcePlanningQuota(request as FastifyRequest<{ Body: PlanningModeBody }>, reply)) return;
        done();
      }],
    },
    async (request, reply) => {
      try {
        const input = planningRequestSchema.parse(request.body);
        const userId = (request as any).userId as string | undefined;
        const db: PrismaClient | null = app.db;

        // Set SSE headers
        reply.header("Content-Type", "text/event-stream");
        reply.header("Cache-Control", "no-cache");
        reply.header("Connection", "keep-alive");

        // ── 1. 创建或获取会话 ──
        let conversationId = (request.body as any).conversationId as string | undefined;
        if (!conversationId) {
          if (db) {
            try {
              const conv = await db.conversation.create({
                data: {
                  userId: userId ?? undefined,
                  guestId: !userId ? ((request.body as any).guestId ?? null) : null,
                  title: input.prompt.length > 30 ? input.prompt.slice(0, 30) + "…" : input.prompt,
                  city: input.city ?? "北京",
                  modelMode: (input as any).modelMode ?? "flash",
                },
              });
              conversationId = conv.id;
            } catch {
              // fallback
            }
          }
          if (!conversationId) {
            const conv = mem.createConversation({
              userId,
              guestId: !userId ? ((request.body as any).guestId ?? null) : null,
              title: input.prompt.length > 30 ? input.prompt.slice(0, 30) + "…" : input.prompt,
              city: input.city,
              modelMode: (input as any).modelMode,
            });
            conversationId = conv.id;
          }
        }

        // ── 2. 保存用户消息 ──
        if (db) {
          try {
            await db.message.create({
              data: { conversationId, role: "user", content: input.prompt },
            });
          } catch {
            mem.addMessage({ conversationId, role: "user", content: input.prompt });
          }
        } else {
          mem.addMessage({ conversationId, role: "user", content: input.prompt });
        }

        // ── 3. 运行规划管道并流式返回 ──
        const result = await runPlanningPipeline({
          ...input,
          providers: app.providers ?? undefined,
          userId,
        });

        // 保存生成的 actions
        if (result.executableActions?.length) {
          saveActions(result.executableActions);
        }

        // Stream the summary
        const summary = result.summary || "为你找到以下方案：";
        for (let i = 0; i < summary.length; i++) {
          reply.raw.write(`data: ${JSON.stringify({ content: summary[i] })}\n\n`);
          await new Promise((resolve) => setTimeout(resolve, 10));
        }

        // Send final structured result for progressive UI hydration
        const finalResult = { ...result, conversationId };
        reply.raw.write(`data: [FINAL_RESULT]${JSON.stringify(finalResult)}\n\n`);
        reply.raw.write(`data: ${JSON.stringify({ done: true, result: finalResult })}\n\n`);
        reply.raw.write("data: [DONE]\n\n");

        // ── 4. 保存助手消息 ──
        if (db) {
          try {
            await db.message.create({
              data: {
                conversationId,
                role: "assistant",
                content: summary,
                payloadJson: { type: "plan", data: { planId: result.planId, options: result.options, summary: result.summary } },
              },
            });
          } catch {
            mem.addMessage({ conversationId, role: "assistant", content: summary });
          }
        } else {
          mem.addMessage({ conversationId, role: "assistant", content: summary });
        }
        reply.raw.end();
      } catch (error) {
        if (error instanceof ZodError) {
          reply.raw.write(`data: ${JSON.stringify({ error: "INVALID_REQUEST", issues: error.issues })}\n\n`);
        } else {
          reply.raw.write(`data: ${JSON.stringify({ error: "INTERNAL_SERVER_ERROR" })}\n\n`);
        }
        reply.raw.write("data: [DONE]\n\n");
        reply.raw.end();
      }
    }
  );

  app.post("/api/agent/plan/legacy", { preHandler: [app.optionalAuthGuard] }, async (request, reply) => {
    try {
      const input = planningRequestSchema.parse(request.body);
      return runPlanningAgent(input);
    } catch (error) {
      if (error instanceof ZodError) {
        return reply.status(400).send({ error: "INVALID_REQUEST", issues: error.issues });
      }
      throw error;
    }
  });

  app.post("/api/agent/what-if", { preHandler: [app.optionalAuthGuard] }, async (request) => {
    const input = z
      .object({
        planId: z.string().default("plan_a"),
        scenario: z.enum(["rain", "late", "budget", "traffic"]),
      })
      .parse(request.body);
    return simulateWhatIf(input.planId, input.scenario);
  });
}

/**
 * Auth 路由 — 注册 / 登录 / Guest / Refresh / Logout
 * 支持 PostgreSQL 和内存 fallback 两种模式
 */

import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { UserRepository } from "../repositories/userRepository.js";
import { ProfileRepository } from "../repositories/profileRepository.js";
import { TokenService } from "../services/tokenService.js";
import { AuthService } from "../services/authService.js";
import * as mem from "../services/memoryStore.js";
import { sendOk, sendCreated, sendNoContent, sendError } from "../common/response.js";
import { env } from "../config/env.js";

const registerSchema = z.object({
  email: z.string().email("邮箱格式不正确"),
  password: z.string().min(6, "密码至少6位"),
  displayName: z.string().max(50).optional(),
  name: z.string().max(50).optional(),
  city: z.string().optional(),
  startPoint: z.string().optional(),
  companions: z.string().optional(),
  budgetMin: z.number().int().optional(),
  budgetMax: z.number().int().optional(),
});

const loginSchema = z.object({
  email: z.string().email(),
  password: z.string().min(1),
});

const refreshTokenSchema = z.object({
  refreshToken: z.string().min(1),
});

const guestProfileSchema = z.object({
  city: z.string().optional(),
  startPoint: z.string().optional(),
  companions: z.enum(["family", "friends", "couple", "solo"]).optional(),
  budgetMin: z.number().int().optional(),
  budgetMax: z.number().int().optional(),
  homeLat: z.number().optional(),
  homeLng: z.number().optional(),
  locationLabel: z.string().optional(),
  locationSource: z.enum(["browser", "manual", "default"]).optional(),
}).optional();

const changePasswordSchema = z.object({
  oldPassword: z.string().min(1).optional(),
  currentPassword: z.string().min(1).optional(),
  newPassword: z.string().min(6),
}).refine((data) => data.oldPassword || data.currentPassword, {
  message: "oldPassword 或 currentPassword 必填其一",
});

function getClientMeta(request: { headers: Record<string, string | string[] | undefined>; ip: string }) {
  return {
    userAgent: typeof request.headers["user-agent"] === "string" ? request.headers["user-agent"] : undefined,
    ipAddress: request.ip,
  };
}

export async function registerAuthRoutes(app: FastifyInstance) {
  // 判断是否使用内存模式
  const useMemory = !app.db;

  if (!useMemory) {
    // ── PostgreSQL 模式 ──
    const db = app.db!;
    const userRepo = new UserRepository(db);
    const profileRepo = new ProfileRepository(db);
    const tokenService = new TokenService(userRepo);
    const authService = new AuthService(userRepo, profileRepo, tokenService);

    app.post("/api/auth/register", async (request, reply) => {
      const body = registerSchema.parse(request.body);
      const displayName = body.displayName ?? body.name ?? body.email.split("@")[0];
      const result = await authService.register(body.email, body.password, displayName, getClientMeta(request));
      // 创建用户画像（如果数据库可用）
      if (app.db && body.city) {
        try {
          await app.db.userProfile.upsert({
            where: { userId: result.user.id },
            update: {
              city: body.city,
              startPoint: body.startPoint,
              companions: body.companions ?? "solo",
              budgetMin: body.budgetMin,
              budgetMax: body.budgetMax,
            },
            create: {
              userId: result.user.id,
              city: body.city,
              startPoint: body.startPoint,
              companions: body.companions ?? "solo",
              budgetMin: body.budgetMin,
              budgetMax: body.budgetMax,
            },
          });
        } catch {
          // 非阻断：画像创建失败不影响注册
        }
      }
      return sendCreated(reply, result);
    });

    app.post("/api/auth/login", async (request, reply) => {
      const body = loginSchema.parse(request.body);
      const result = await authService.login(body.email, body.password, getClientMeta(request));
      return sendOk(reply, result);
    });

    app.post("/api/auth/guest", async (request, reply) => {
      const profile = guestProfileSchema.parse(request.body) ?? undefined;
      const result = await authService.guestLogin(getClientMeta(request), profile);
      return sendCreated(reply, result);
    });

    app.post("/api/auth/demo", async (request, reply) => {
      if (!env.ENABLE_DEMO_AUTH) {
        return sendError(reply, 404, "NOT_FOUND", "Not found");
      }
      const result = await authService.demoLogin(getClientMeta(request));
      return sendOk(reply, result);
    });

    app.post("/api/auth/refresh", async (request, reply) => {
      const body = refreshTokenSchema.parse(request.body);
      const result = await tokenService.refreshTokens(body.refreshToken, getClientMeta(request));
      if (!result) return sendError(reply, 401, "TOKEN_EXPIRED", "Refresh token 无效或已过期");
      return sendOk(reply, result);
    });

    app.post("/api/auth/logout", { preHandler: [app.optionalAuthGuard] }, async (request, reply) => {
      const body = refreshTokenSchema.parse(request.body);
      await tokenService.revokeRefreshToken(body.refreshToken);
      return sendNoContent(reply);
    });

    app.post("/api/auth/logout-all", { preHandler: [app.authGuard] }, async (request, reply) => {
      await tokenService.revokeAllTokens(request.userId!);
      return sendNoContent(reply);
    });

    app.post("/api/auth/change-password", { preHandler: [app.authGuard] }, async (request, reply) => {
      const body = changePasswordSchema.parse(request.body);
      const oldPassword = body.oldPassword ?? body.currentPassword!;
      await authService.changePassword(request.userId!, oldPassword, body.newPassword);
      return sendNoContent(reply);
    });

    return;
  }

  // ── 内存 fallback 模式 ──
  app.log.info("📝 Auth routes using in-memory store (no PostgreSQL)");

  app.post("/api/auth/register", async (request, reply) => {
    const body = registerSchema.parse(request.body);
    const displayName = body.displayName ?? body.name ?? body.email.split("@")[0];
    try {
      const result = await mem.register(body.email, body.password, displayName, getClientMeta(request));
      return sendCreated(reply, result);
    } catch (err: any) {
      return sendError(reply, 409, "EMAIL_EXISTS", err.message);
    }
  });

  app.post("/api/auth/login", async (request, reply) => {
    const body = loginSchema.parse(request.body);
    try {
      const result = await mem.login(body.email, body.password, getClientMeta(request));
      return sendOk(reply, result);
    } catch (err: any) {
      return sendError(reply, 401, "INVALID_CREDENTIALS", err.message);
    }
  });

  app.post("/api/auth/guest", async (request, reply) => {
    const profile = guestProfileSchema.parse(request.body) ?? undefined;
    const result = await mem.guestLogin(getClientMeta(request), profile);
    return sendCreated(reply, result);
  });

  app.post("/api/auth/demo", async (request, reply) => {
    if (!env.ENABLE_DEMO_AUTH) {
      return sendError(reply, 404, "NOT_FOUND", "Not found");
    }
    const result = await mem.demoLogin(getClientMeta(request));
    return sendOk(reply, result);
  });

  app.post("/api/auth/refresh", async (request, reply) => {
    const body = refreshTokenSchema.parse(request.body);
    const result = mem.refreshTokens(body.refreshToken, getClientMeta(request));
    if (!result) return sendError(reply, 401, "TOKEN_EXPIRED", "Refresh token 无效或已过期");
    return sendOk(reply, result);
  });

  app.post("/api/auth/logout", { preHandler: [app.optionalAuthGuard] }, async (request, reply) => {
    return sendNoContent(reply);
  });

  app.post("/api/auth/logout-all", { preHandler: [app.authGuard] }, async (request, reply) => {
    mem.revokeAllRefreshTokens(request.userId!);
    return sendNoContent(reply);
  });

  app.post("/api/auth/change-password", { preHandler: [app.authGuard] }, async (request, reply) => {
    return sendError(reply, 501, "NOT_IMPLEMENTED", "内存模式不支持修改密码，请连接 PostgreSQL");
  });
}

/**
 * Conversations & Messages 路由 — /api/conversations/*
 */

import type { FastifyInstance } from "fastify";
import type { PrismaClient } from "../../generated/prisma/client.js";
import { z } from "zod";
import { sendOk, sendCreated, sendNoContent, sendError } from "../common/response.js";
import { UnauthorizedError } from "../common/errors.js";
import * as mem from "../services/memoryStore.js";

function optionalUid(request: { userId?: string }): string | null {
  return request.userId ?? null;
}

export async function registerConversationRoutes(app: FastifyInstance) {
  // ── 创建会话 ──
  app.post("/api/conversations", { preHandler: [app.optionalAuthGuard] }, async (request, reply) => {
    const body = z
      .object({
        title: z.string().max(100).optional(),
        city: z.string().optional(),
        modelMode: z.enum(["flash", "pro"]).optional(),
        guestId: z.string().optional(),
      })
      .parse(request.body);

    const userId = optionalUid(request);
    const db: PrismaClient | null = app.db;

    if (db) {
      try {
        const conv = await db.conversation.create({
          data: {
            userId: userId ?? undefined,
            guestId: !userId ? (body.guestId ?? null) : null,
            title: body.title ?? "新规划",
            city: body.city ?? "北京",
            modelMode: body.modelMode ?? "flash",
          },
        });
        return sendCreated(reply, conv);
      } catch {
        // fallback to memory
      }
    }

    const conv = mem.createConversation({
      userId,
      guestId: !userId ? (body.guestId ?? null) : null,
      title: body.title,
      city: body.city,
      modelMode: body.modelMode,
    });
    return sendCreated(reply, conv);
  });

  // ── 获取会话列表 ──
  app.get("/api/conversations", { preHandler: [app.optionalAuthGuard] }, async (request, reply) => {
    const query = z
      .object({
        guestId: z.string().optional(),
        limit: z.coerce.number().int().min(1).max(100).default(50),
      })
      .parse(request.query);

    const userId = optionalUid(request);
    const db: PrismaClient | null = app.db;

    if (db) {
      try {
        const where: any = {};
        if (userId) where.userId = userId;
        else if (query.guestId) where.guestId = query.guestId;
        else return sendOk(reply, []);

        const convs = await db.conversation.findMany({
          where,
          orderBy: { updatedAt: "desc" },
          take: query.limit,
          include: { _count: { select: { messages: true, plans: true } } },
        });
        return sendOk(reply, convs);
      } catch {
        // fallback
      }
    }

    const convs = mem.listConversations({
      userId: userId ?? undefined,
      guestId: !userId ? query.guestId : undefined,
      limit: query.limit,
    });
    return sendOk(reply, convs);
  });

  // ── 获取单个会话详情 ──
  app.get("/api/conversations/:id", { preHandler: [app.optionalAuthGuard] }, async (request, reply) => {
    const { id } = z.object({ id: z.string().uuid() }).parse(request.params);
    const db: PrismaClient | null = app.db;

    if (db) {
      try {
        const conv = await db.conversation.findUnique({
          where: { id },
          include: {
            messages: { orderBy: { createdAt: "asc" } },
            plans: { include: { options: { include: { steps: true } }, execActions: true } },
          },
        });
        if (!conv) return sendError(reply, 404, "NOT_FOUND", "会话不存在");
        return sendOk(reply, conv);
      } catch {
        // fallback
      }
    }

    const conv = mem.getConversation(id);
    if (!conv) return sendError(reply, 404, "NOT_FOUND", "会话不存在");
    const msgs = mem.listMessages(id);
    const plans = mem.listPlans({ conversationId: id });
    return sendOk(reply, { ...conv, messages: msgs, plans });
  });

  // ── 添加消息 ──
  app.post("/api/conversations/:id/messages", { preHandler: [app.optionalAuthGuard] }, async (request, reply) => {
    const params = z.object({ id: z.string().uuid() }).parse(request.params);
    const body = z
      .object({
        role: z.enum(["user", "assistant", "system"]),
        content: z.string().max(10000),
        payloadJson: z.any().optional(),
      })
      .parse(request.body);

    const db: PrismaClient | null = app.db;

    if (db) {
      try {
        const msg = await db.message.create({
          data: {
            conversationId: params.id,
            role: body.role,
            content: body.content,
            payloadJson: body.payloadJson ?? undefined,
          },
        });
        // Update conversation updatedAt
        await db.conversation.update({
          where: { id: params.id },
          data: { updatedAt: new Date() },
        });
        return sendCreated(reply, msg);
      } catch {
        // fallback
      }
    }

    const conv = mem.getConversation(params.id);
    if (!conv) return sendError(reply, 404, "NOT_FOUND", "会话不存在");
    const msg = mem.addMessage({
      conversationId: params.id,
      role: body.role,
      content: body.content,
      payloadJson: body.payloadJson,
    });
    return sendCreated(reply, msg);
  });

  // ── 获取消息列表 ──
  app.get("/api/conversations/:id/messages", { preHandler: [app.optionalAuthGuard] }, async (request, reply) => {
    const { id } = z.object({ id: z.string().uuid() }).parse(request.params);
    const db: PrismaClient | null = app.db;

    if (db) {
      try {
        const msgs = await db.message.findMany({
          where: { conversationId: id },
          orderBy: { createdAt: "asc" },
        });
        return sendOk(reply, msgs);
      } catch {
        // fallback
      }
    }

    return sendOk(reply, mem.listMessages(id));
  });

  // ── 收藏方案 ──
  app.post("/api/plans/:id/favorite", { preHandler: [app.optionalAuthGuard] }, async (request, reply) => {
    const { id } = z.object({ id: z.string().uuid() }).parse(request.params);
    const db: PrismaClient | null = app.db;

    if (db) {
      try {
        const plan = await db.plan.findUnique({ where: { id } });
        if (!plan) return sendError(reply, 404, "NOT_FOUND", "方案不存在");
        const updated = await db.plan.update({
          where: { id },
          data: { favorite: !plan.favorite },
        });
        return sendOk(reply, { id: updated.id, favorite: updated.favorite });
      } catch {
        // fallback
      }
    }

    const result = mem.togglePlanFavorite(id);
    if (result === null) return sendError(reply, 404, "NOT_FOUND", "方案不存在");
    return sendOk(reply, { id, favorite: result });
  });

  // ── 获取收藏方案列表 ──
  app.get("/api/plans/favorites", { preHandler: [app.optionalAuthGuard] }, async (request, reply) => {
    const userId = optionalUid(request);
    if (!userId) return sendOk(reply, []);

    const db: PrismaClient | null = app.db;
    if (db) {
      try {
        const plans = await db.plan.findMany({
          where: { userId, favorite: true },
          orderBy: { updatedAt: "desc" },
          include: { options: { include: { steps: true } } },
        });
        return sendOk(reply, plans);
      } catch {
        // fallback
      }
    }

    return sendOk(reply, mem.listPlans({ userId, favoritesOnly: true }));
  });
}

/**
 * Developer 路由 — 完整开发者控制台 API
 * Dashboard / Apps / API Keys / Usage / Request Logs / Webhooks / Sandbox / Security
 */

import type { FastifyInstance, FastifyRequest } from "fastify";
import { z } from "zod";
import { sendOk, sendCreated, sendNoContent, sendError } from "../common/response.js";
import { UnauthorizedError } from "../common/errors.js";
import { DeveloperRepository } from "../repositories/developerRepository.js";

function uid(req: FastifyRequest): string {
  const id = (req as any).userId;
  if (!id) throw new UnauthorizedError("未登录");
  return id;
}

/** 脱敏请求体：移除敏感字段 */
function sanitizePreview(obj: Record<string, unknown> | null | undefined): Record<string, unknown> {
  if (!obj || typeof obj !== "object") return {};
  const sensitive = new Set(["password", "token", "authorization", "apiKey", "refreshToken", "accessToken", "secret", "keyHash"]);
  const result: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(obj)) {
    if (sensitive.has(k)) {
      result[k] = "***";
    } else {
      result[k] = v;
    }
  }
  return result;
}

export async function registerDeveloperRoutes(app: FastifyInstance) {
  if (!app.db) {
    app.log.warn("Developer routes disabled (no PostgreSQL)");
    return;
  }
  const db = app.db;
  const repo = new DeveloperRepository(db);

  // ── Dashboard ──
  app.get("/api/developer/dashboard", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const dashboard = await repo.getDashboardSummary(userId);
    return sendOk(reply, dashboard);
  });

  // ── Developer Apps ──
  app.get("/api/developer/apps", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const apps = await repo.listApps(userId);
    return sendOk(reply, apps);
  });

  app.post("/api/developer/apps", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const input = z.object({
      name: z.string().min(1).max(64),
      description: z.string().max(256).default(""),
      environment: z.enum(["sandbox", "production"]).default("sandbox"),
      callbackDomain: z.string().default(""),
    }).parse(request.body);

    const app = await repo.createApp(userId, input);
    return sendCreated(reply, app);
  });

  app.patch("/api/developer/apps/:id", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);
    const input = z.object({
      name: z.string().min(1).max(64).optional(),
      description: z.string().max(256).optional(),
      environment: z.enum(["sandbox", "production"]).optional(),
      callbackDomain: z.string().optional(),
      status: z.enum(["active", "paused"]).optional(),
    }).parse(request.body);

    const updated = await repo.updateApp(id, userId, input);
    if (!updated) return sendError(reply, 404, "APP_NOT_FOUND", "应用不存在");
    return sendOk(reply, updated);
  });

  app.delete("/api/developer/apps/:id", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);

    const deleted = await repo.deleteApp(id, userId);
    if (!deleted) return sendError(reply, 404, "APP_NOT_FOUND", "应用不存在");
    return sendNoContent(reply);
  });

  // ── API Keys ──
  app.get("/api/developer/api-keys", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const keys = await repo.listApiKeys(userId);
    return sendOk(reply, keys.map(mapApiKey));
  });

  // 兼容旧路径
  app.get("/api/developer/apikeys", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const keys = await repo.listApiKeys(userId);
    return sendOk(reply, keys.map(mapApiKey));
  });

  app.post("/api/developer/api-keys", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const input = z.object({
      name: z.string().min(1).max(64),
      appId: z.string().optional(),
      scopes: z.array(z.string()).default(["plan:read"]),
      environment: z.enum(["sandbox", "production"]).default("sandbox"),
      expiresIn: z.enum(["30d", "90d", "never"]).default("90d"),
    }).parse(request.body);

    let expiresAt: Date | undefined;
    if (input.expiresIn === "30d") {
      expiresAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000);
    } else if (input.expiresIn === "90d") {
      expiresAt = new Date(Date.now() + 90 * 24 * 60 * 60 * 1000);
    }

    const { apiKey, rawKey, prefix } = await repo.createApiKey(userId, {
      name: input.name,
      appId: input.appId,
      scopes: input.scopes,
      environment: input.environment,
      expiresAt,
    });

    // 写审计日志
    await db.auditLog.create({
      data: {
        userId,
        action: "api_key.created",
        resourceType: "api_key",
        resourceId: apiKey.id,
        traceId: (request as any).traceId ?? "",
      },
    });

    return sendCreated(reply, { ...mapApiKey(apiKey), key: rawKey });
  });

  // 兼容旧路径
  app.post("/api/developer/apikeys", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const input = z.object({
      name: z.string().default("Default Key"),
      scopes: z.array(z.string()).default(["plan:read"]),
    }).parse(request.body ?? {});

    const { apiKey, rawKey } = await repo.createApiKey(userId, {
      name: input.name,
      scopes: input.scopes,
    });

    return sendCreated(reply, { ...mapApiKey(apiKey), key: rawKey });
  });

  app.post("/api/developer/api-keys/:id/revoke", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);

    const revoked = await repo.revokeApiKey(id, userId);
    if (!revoked) return sendError(reply, 404, "API_KEY_NOT_FOUND", "API Key 不存在");

    await db.auditLog.create({
      data: {
        userId,
        action: "api_key.revoked",
        resourceType: "api_key",
        resourceId: id,
        traceId: (request as any).traceId ?? "",
      },
    });

    return sendOk(reply, mapApiKey(revoked));
  });

  // 兼容旧路径
  app.delete("/api/developer/apikeys/:id", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);

    const revoked = await repo.revokeApiKey(id, userId);
    if (!revoked) return sendError(reply, 404, "API_KEY_NOT_FOUND", "API Key 不存在");
    return sendOk(reply, mapApiKey(revoked));
  });

  app.post("/api/developer/api-keys/revoke-all", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const count = await repo.revokeAllApiKeys(userId);

    await db.auditLog.create({
      data: {
        userId,
        action: "api_key.revoked_all",
        resourceType: "api_key",
        resourceId: "",
        metadata: { count },
        traceId: (request as any).traceId ?? "",
      },
    });

    return sendOk(reply, { revokedCount: count });
  });

  // ── Usage ──
  app.get("/api/developer/usage", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const query = z.object({
      range: z.enum(["7d", "30d", "90d"]).default("7d"),
    }).parse(request.query);

    const days = query.range === "30d" ? 30 : query.range === "90d" ? 90 : 7;
    const usage = await repo.getUsageSummary(userId, days);
    return sendOk(reply, usage);
  });

  // ── Request Logs ──
  app.get("/api/developer/request-logs", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const query = z.object({
      page: z.coerce.number().int().min(1).default(1),
      pageSize: z.coerce.number().int().min(1).max(100).default(20),
      status: z.enum(["all", "success", "error"]).default("all"),
      path: z.string().optional(),
      traceId: z.string().optional(),
    }).parse(request.query);

    const result = await repo.listRequestLogs(userId, {
      page: query.page,
      pageSize: query.pageSize,
      status: query.status === "all" ? undefined : query.status,
      path: query.path,
      traceId: query.traceId,
    });

    return sendOk(reply, {
      ...result,
      items: result.items.map(mapRequestLog),
    });
  });

  app.get("/api/developer/request-logs/:id", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);

    const log = await repo.findRequestLogById(id, userId);
    if (!log) return sendError(reply, 404, "LOG_NOT_FOUND", "请求记录不存在");

    return sendOk(reply, {
      ...mapRequestLog(log),
      requestPreview: sanitizePreview(log.requestPreview as Record<string, unknown>),
      responsePreview: sanitizePreview(log.responsePreview as Record<string, unknown>),
    });
  });

  // ── Webhooks ──
  app.get("/api/developer/webhooks", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const hooks = await repo.listWebhooks(userId);
    return sendOk(reply, hooks.map(mapWebhook));
  });

  app.post("/api/developer/webhooks", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const input = z.object({
      url: z.string().url(),
      events: z.array(z.string()).min(1),
      appId: z.string().optional(),
    }).parse(request.body);

    const { webhook, secret } = await repo.createWebhook(userId, input);

    await db.auditLog.create({
      data: {
        userId,
        action: "webhook.created",
        resourceType: "webhook",
        resourceId: webhook.id,
        traceId: (request as any).traceId ?? "",
      },
    });

    return sendCreated(reply, { ...mapWebhook(webhook), secret });
  });

  app.patch("/api/developer/webhooks/:id", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);
    const input = z.object({
      url: z.string().url().optional(),
      events: z.array(z.string()).optional(),
      enabled: z.boolean().optional(),
      appId: z.string().optional(),
    }).parse(request.body);

    const updated = await repo.updateWebhook(id, userId, input);
    if (!updated) return sendError(reply, 404, "WEBHOOK_NOT_FOUND", "Webhook 不存在");
    return sendOk(reply, mapWebhook(updated));
  });

  app.delete("/api/developer/webhooks/:id", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);

    const deleted = await repo.deleteWebhook(id, userId);
    if (!deleted) return sendError(reply, 404, "WEBHOOK_NOT_FOUND", "Webhook 不存在");
    return sendNoContent(reply);
  });

  app.post("/api/developer/webhooks/:id/test", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);

    const webhook = await repo.findWebhookById(id, userId);
    if (!webhook) return sendError(reply, 404, "WEBHOOK_NOT_FOUND", "Webhook 不存在");

    const startTime = Date.now();
    const events = webhook.events as string[];
    const testEvent = events[0] ?? "plan.created";

    const delivery = await repo.recordDelivery({
      webhookId: id,
      event: testEvent,
      payload: {
        type: testEvent,
        data: { test: true, message: "这是一条测试投递" },
        timestamp: new Date().toISOString(),
      },
      status: "success",
      responseStatus: 200,
      latencyMs: Date.now() - startTime,
    });

    return sendOk(reply, delivery);
  });

  app.post("/api/developer/webhooks/:id/replay", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);

    const webhook = await repo.findWebhookById(id, userId);
    if (!webhook) return sendError(reply, 404, "WEBHOOK_NOT_FOUND", "Webhook 不存在");

    const events = webhook.events as string[];
    const delivery = await repo.recordDelivery({
      webhookId: id,
      event: events[0] ?? "plan.created",
      payload: { replay: true, timestamp: new Date().toISOString() },
      status: "success",
      responseStatus: 200,
    });

    return sendOk(reply, delivery);
  });

  app.get("/api/developer/webhook-deliveries", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const query = z.object({
      webhookId: z.string().optional(),
      limit: z.coerce.number().int().min(1).max(100).default(50),
    }).parse(request.query);

    if (query.webhookId) {
      const webhook = await repo.findWebhookById(query.webhookId, userId);
      if (!webhook) return sendError(reply, 404, "WEBHOOK_NOT_FOUND", "Webhook 不存在");
      const deliveries = await repo.getDeliveriesByWebhookId(query.webhookId, query.limit);
      return sendOk(reply, deliveries);
    }

    const deliveries = await repo.getAllDeliveries(userId, query.limit);
    return sendOk(reply, deliveries);
  });

  app.post("/api/developer/webhooks/:id/rotate-secret", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);

    const result = await repo.rotateWebhookSecret(id, userId);
    if (!result) return sendError(reply, 404, "WEBHOOK_NOT_FOUND", "Webhook 不存在");

    return sendOk(reply, { ...mapWebhook(result.webhook), secret: result.secret });
  });

  // ── Sandbox ──
  app.post("/api/developer/sandbox/run", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);
    const input = z.object({
      endpoint: z.string(),
      method: z.enum(["GET", "POST"]).default("POST"),
      body: z.record(z.string(), z.unknown()).optional(),
    }).parse(request.body);

    const startTime = Date.now();
    const traceId = (request as any).traceId ?? `sbx_${Date.now()}`;

    try {
      // 转发到实际业务接口
      let result: unknown;
      const body = JSON.stringify(input.body ?? {});

      const response = await app.inject({
        method: input.method,
        url: input.endpoint,
        payload: input.body ?? {},
        headers: {
          authorization: request.headers.authorization ?? "",
          "content-type": "application/json",
        },
      });

      const latencyMs = Date.now() - startTime;
      let responseBody: unknown;
      try {
        responseBody = JSON.parse(response.payload);
      } catch {
        responseBody = response.payload;
      }

      // 记录请求日志
      await repo.createRequestLog(userId, {
        method: input.method,
        path: input.endpoint,
        statusCode: response.statusCode,
        latencyMs,
        traceId,
        requestPreview: sanitizePreview(input.body as Record<string, unknown>),
        responsePreview: { statusCode: response.statusCode, body: responseBody },
      });

      return sendOk(reply, {
        traceId,
        statusCode: response.statusCode,
        latencyMs,
        body: responseBody,
      });
    } catch (error) {
      const latencyMs = Date.now() - startTime;
      const errorMessage = error instanceof Error ? error.message : "请求失败";

      await repo.createRequestLog(userId, {
        method: input.method,
        path: input.endpoint,
        statusCode: 500,
        latencyMs,
        traceId,
        errorCode: "SANDBOX_ERROR",
        requestPreview: sanitizePreview(input.body as Record<string, unknown>),
        responsePreview: { error: errorMessage },
      });

      return sendOk(reply, {
        traceId,
        statusCode: 500,
        latencyMs,
        body: { error: errorMessage },
      });
    }
  });

  // ── Security ──
  app.get("/api/developer/security", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = uid(request);

    const [apiKeys, webhooks, recentAudits] = await Promise.all([
      repo.listApiKeys(userId),
      repo.listWebhooks(userId),
      db.auditLog.findMany({
        where: { userId },
        orderBy: { createdAt: "desc" },
        take: 10,
        select: { action: true, resourceType: true, createdAt: true, traceId: true },
      }),
    ]);

    return sendOk(reply, {
      activeKeys: apiKeys.filter((k) => k.status === "active").length,
      totalKeys: apiKeys.length,
      activeWebhooks: webhooks.filter((w) => w.enabled).length,
      totalWebhooks: webhooks.length,
      recentAudits,
      ipAllowlist: null,
      ipAllowlistEnabled: false,
    });
  });
}

// ── Helpers ──

function mapApiKey(key: any) {
  return {
    id: key.id,
    name: key.name,
    prefix: key.prefix,
    scopes: key.scopes,
    status: key.status,
    environment: key.environment ?? "sandbox",
    appId: key.appId,
    expiresAt: key.expiresAt,
    lastUsedAt: key.lastUsedAt,
    createdAt: key.createdAt,
  };
}

function mapWebhook(hook: any) {
  return {
    id: hook.id,
    url: hook.url,
    events: hook.events ?? [hook.event],
    enabled: hook.enabled,
    appId: hook.appId,
    secret: hook.secretHash ? "••••••••" : undefined,
    createdAt: hook.createdAt,
    updatedAt: hook.updatedAt,
  };
}

function mapRequestLog(log: any) {
  return {
    id: log.id,
    method: log.method,
    path: log.path,
    statusCode: log.statusCode,
    latencyMs: log.latencyMs,
    traceId: log.traceId,
    errorCode: log.errorCode,
    apiKeyPrefix: log.apiKeyPrefix,
    appId: log.appId,
    createdAt: log.createdAt,
  };
}

/**
 * Events & Client Errors 路由 — /api/events, /api/client-errors
 */

import type { FastifyInstance } from "fastify";
import type { PrismaClient } from "../../generated/prisma/client.js";
import { z } from "zod";
import { sendOk, sendCreated, sendError } from "../common/response.js";
import * as mem from "../services/memoryStore.js";

export async function registerEventRoutes(app: FastifyInstance) {
  // ── 记录用户事件 ──
  app.post("/api/events", { preHandler: [app.optionalAuthGuard] }, async (request, reply) => {
    const body = z
      .object({
        eventName: z.string().min(1).max(100),
        payload: z.any().optional(),
        page: z.string().max(200).optional(),
        guestId: z.string().optional(),
        conversationId: z.string().optional(),
      })
      .parse(request.body);

    const userId = (request as any).userId as string | undefined;
    const db: PrismaClient | null = app.db;

    if (db) {
      try {
        const evt = await db.userEvent.create({
          data: {
            userId: userId ?? undefined,
            guestId: !userId ? (body.guestId ?? null) : null,
            conversationId: body.conversationId ?? null,
            eventName: body.eventName,
            eventPayloadJson: body.payload ?? {},
            page: body.page ?? "",
            traceId: (request as any).traceId ?? "",
          },
        });
        return sendCreated(reply, { id: evt.id });
      } catch {
        // fallback
      }
    }

    const evt = mem.trackEvent({
      userId,
      guestId: !userId ? body.guestId : undefined,
      conversationId: body.conversationId,
      eventName: body.eventName,
      eventPayloadJson: body.payload,
      page: body.page,
      traceId: (request as any).traceId,
    });
    return sendCreated(reply, { id: evt.id });
  });

  // ── 批量记录事件（可选） ──
  app.post("/api/events/batch", { preHandler: [app.optionalAuthGuard] }, async (request, reply) => {
    const body = z
      .object({
        events: z.array(z.object({
          eventName: z.string().min(1).max(100),
          payload: z.any().optional(),
          page: z.string().max(200).optional(),
          guestId: z.string().optional(),
          conversationId: z.string().optional(),
        })).min(1).max(50),
      })
      .parse(request.body);

    const userId = (request as any).userId as string | undefined;
    const db: PrismaClient | null = app.db;
    const ids: string[] = [];

    for (const evt of body.events) {
      if (db) {
        try {
          const created = await db.userEvent.create({
            data: {
              userId: userId ?? undefined,
              guestId: !userId ? (evt.guestId ?? null) : null,
              conversationId: evt.conversationId ?? null,
              eventName: evt.eventName,
              eventPayloadJson: evt.payload ?? {},
              page: evt.page ?? "",
              traceId: (request as any).traceId ?? "",
            },
          });
          ids.push(created.id);
          continue;
        } catch {
          // fallback
        }
      }
      const created = mem.trackEvent({
        userId,
        guestId: !userId ? evt.guestId : undefined,
        conversationId: evt.conversationId,
        eventName: evt.eventName,
        eventPayloadJson: evt.payload,
        page: evt.page,
        traceId: (request as any).traceId,
      });
      ids.push(created.id);
    }

    return sendCreated(reply, { ids, count: ids.length });
  });

  // ── 客户端错误日志 ──
  app.post("/api/client-errors", { preHandler: [app.optionalAuthGuard] }, async (request, reply) => {
    const body = z
      .object({
        message: z.string().min(1).max(2000),
        stack: z.string().max(5000).optional(),
        route: z.string().max(200).optional(),
        guestId: z.string().optional(),
        payload: z.any().optional(),
      })
      .parse(request.body);

    const userId = (request as any).userId as string | undefined;
    const db: PrismaClient | null = app.db;

    if (db) {
      try {
        const log = await db.errorLog.create({
          data: {
            userId: userId ?? undefined,
            guestId: !userId ? (body.guestId ?? null) : null,
            traceId: (request as any).traceId ?? "",
            route: body.route ?? "",
            message: body.message,
            stack: body.stack ?? null,
            payloadJson: body.payload ?? null,
          },
        });
        return sendCreated(reply, { id: log.id });
      } catch {
        // fallback
      }
    }

    const log = mem.logClientError({
      userId,
      guestId: !userId ? body.guestId : undefined,
      traceId: (request as any).traceId,
      route: body.route,
      message: body.message,
      stack: body.stack,
      payloadJson: body.payload,
    });
    return sendCreated(reply, { id: log.id });
  });
}

import type { FastifyInstance } from "fastify";
import { createMobileHandoff, getHandoffByToken, claimHandoff, getHandoffStatus, consumeHandoff } from "../modules/handoff/qrService";
import type { PermissionScope } from "../modules/agent/middleware/permissionGuard";

export async function registerHandoffRoutes(fastify: FastifyInstance) {
  /**
   * Create a mobile handoff session
   * POST /api/handoff/mobile
   */
  fastify.post("/api/handoff/mobile", async (request, reply) => {
    const body = request.body as {
      conversationId: string;
      planId: string;
      selectedOptionId?: string;
      scopes: PermissionScope[];
    };

    try {
      const userId = (request as any).userId;
      const guestId = (request as any).guestId;

      const result = await createMobileHandoff({
        conversationId: body.conversationId,
        planId: body.planId,
        selectedOptionId: body.selectedOptionId,
        userId,
        guestId,
        scopes: body.scopes,
      });

      return reply.send(result);
    } catch (error) {
      fastify.log.error(error);
      return reply.status(500).send({ error: "Failed to create handoff session" });
    }
  });

  /**
   * Get handoff session by token
   * GET /api/handoff/mobile/:token
   */
  fastify.get("/api/handoff/mobile/:token", async (request, reply) => {
    const { token } = request.params as { token: string };

    try {
      const payload = await getHandoffByToken(token);

      if (!payload) {
        return reply.status(404).send({ error: "Handoff session not found or expired" });
      }

      return reply.send(payload);
    } catch (error) {
      fastify.log.error(error);
      return reply.status(500).send({ error: "Failed to get handoff session" });
    }
  });

  /**
   * Claim a handoff session (mobile device scans QR code)
   * POST /api/handoff/mobile/:token/claim
   */
  fastify.post("/api/handoff/mobile/:token/claim", async (request, reply) => {
    const { token } = request.params as { token: string };
    const body = request.body as {
      deviceId: string;
      guestId?: string;
      grantedScopes: PermissionScope[];
    };

    try {
      const result = await claimHandoff({
        token,
        deviceId: body.deviceId,
        guestId: body.guestId,
        grantedScopes: body.grantedScopes,
      });

      return reply.send(result);
    } catch (error) {
      fastify.log.error(error);
      if (error instanceof Error && error.message.includes("not found")) {
        return reply.status(404).send({ error: error.message });
      }
      if (error instanceof Error && error.message.includes("expired")) {
        return reply.status(410).send({ error: error.message });
      }
      return reply.status(500).send({ error: "Failed to claim handoff session" });
    }
  });

  /**
   * Get handoff status
   * GET /api/handoff/mobile/:handoffId/status
   */
  fastify.get("/api/handoff/mobile/:handoffId/status", async (request, reply) => {
    const { handoffId } = request.params as { handoffId: string };

    try {
      const status = await getHandoffStatus(handoffId);
      return reply.send(status);
    } catch (error) {
      fastify.log.error(error);
      if (error instanceof Error && error.message.includes("not found")) {
        return reply.status(404).send({ error: error.message });
      }
      return reply.status(500).send({ error: "Failed to get handoff status" });
    }
  });

  /**
   * Authorize actions for a handoff session
   * POST /api/handoff/mobile/:handoffId/authorize
   */
  fastify.post("/api/handoff/mobile/:handoffId/authorize", async (request, reply) => {
    const { handoffId } = request.params as { handoffId: string };
    const body = request.body as {
      scopes: PermissionScope[];
    };

    try {
      // In production, this would update the handoff session with authorized scopes
      // For now, just return success
      return reply.send({ success: true, handoffId });
    } catch (error) {
      fastify.log.error(error);
      return reply.status(500).send({ error: "Failed to authorize handoff session" });
    }
  });
}

/**
 * Memory 路由 — Prisma 版
 */

import type { FastifyInstance, FastifyRequest } from "fastify";
import { z } from "zod";
import { sendOk, sendCreated, sendNoContent, sendError } from "../common/response.js";
import { UnauthorizedError } from "../common/errors.js";

function uid(req: FastifyRequest): string {
  const id = (req as any).userId;
  if (!id) throw new UnauthorizedError("未登录");
  return id;
}

export async function registerMemoryRoutes(app: FastifyInstance) {
  if (!app.db) {
    // 内存模式：返回空数据
    app.get("/api/memories", { preHandler: [app.authGuard] }, async (_req, reply) => sendOk(reply, []));
    app.post("/api/memories", { preHandler: [app.authGuard] }, async (_req, reply) => sendError(reply, 501, "NOT_IMPLEMENTED", "内存模式不支持记忆功能"));
    return;
  }
  const db = app.db;

  // GET /api/memories — 返回数组（前端直接用）
  app.get("/api/memories", async (request, reply) => {
    const userId = uid(request);
    const memories = await db.memory.findMany({
      where: { userId, deletedAt: null },
      orderBy: { weight: "desc" },
    });
    return sendOk(reply, memories);
  });

  // POST /api/memories — 创建记忆
  app.post("/api/memories", async (request, reply) => {
    const userId = uid(request);
    const input = z
      .object({
        category: z.enum(["family", "food", "route", "collaboration"]),
        title: z.string().min(1),
        detail: z.string(),
        weight: z.number().min(0).max(1).default(0.5),
      })
      .parse(request.body);

    const memory = await db.memory.create({
      data: { userId, ...input },
    });
    return sendCreated(reply, memory);
  });

  // PATCH /api/memories/:id — 更新记忆
  app.patch("/api/memories/:id", async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);
    const body = z
      .object({
        category: z.enum(["family", "food", "route", "collaboration"]).optional(),
        title: z.string().min(1).optional(),
        detail: z.string().optional(),
        weight: z.number().min(0).max(1).optional(),
      })
      .parse(request.body);

    const existing = await db.memory.findFirst({ where: { id, userId, deletedAt: null } });
    if (!existing) return sendError(reply, 404, "MEMORY_NOT_FOUND", "记忆不存在");

    const memory = await db.memory.update({ where: { id }, data: body });
    return sendOk(reply, memory);
  });

  // DELETE /api/memories/:id — 软删除记忆
  app.delete("/api/memories/:id", async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);

    const existing = await db.memory.findFirst({ where: { id, userId, deletedAt: null } });
    if (!existing) return sendError(reply, 404, "MEMORY_NOT_FOUND", "记忆不存在");

    await db.memory.update({ where: { id }, data: { deletedAt: new Date() } });
    return sendNoContent(reply);
  });
}

/**
 * Privacy 路由 — 数据导出、记忆清除、账号删除
 */

import type { FastifyInstance } from "fastify";
import type { PrismaClient } from "../../generated/prisma/client.js";
import { sendOk, sendNoContent } from "../common/response.js";

export async function registerPrivacyRoutes(app: FastifyInstance) {
  if (!app.db) {
    app.post("/api/privacy/export", { preHandler: [app.authGuard] }, async (_req, reply) => sendOk(reply, { user: {}, profile: {}, plans: [], memories: [], actions: [] }));
    app.delete("/api/privacy/memories", { preHandler: [app.authGuard] }, async (_req, reply) => sendOk(reply, { deleted: 0 }));
    return;
  }
  const db = app.db;

  // POST /api/privacy/export — 导出用户数据
  app.post("/api/privacy/export", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = request.userId!;

    const [user, profile, permissions, plans, memories, companions, notifications, sessions, apiKeys, webhooks] =
      await Promise.all([
        db.user.findUnique({
          where: { id: userId },
          select: { id: true, email: true, displayName: true, role: true, mode: true, createdAt: true },
        }),
        db.userProfile.findUnique({ where: { userId } }),
        db.userPermission.findUnique({ where: { userId } }),
        db.plan.findMany({ where: { userId }, orderBy: { createdAt: "desc" } }),
        db.memory.findMany({ where: { userId, deletedAt: null } }),
        db.companion.findMany({ where: { userId } }),
        db.notification.findMany({ where: { userId } }),
        db.userSession.findMany({ where: { userId }, select: { id: true, userAgent: true, ipAddress: true, createdAt: true, lastSeenAt: true } }),
        db.apiKey.findMany({ where: { userId }, select: { id: true, name: true, prefix: true, status: true, createdAt: true } }),
        db.webhook.findMany({ where: { userId }, select: { id: true, url: true, events: true, enabled: true, createdAt: true } }),
      ]);

    sendOk(reply, {
      exportedAt: new Date().toISOString(),
      user, profile, permissions, plans, memories, companions, notifications, sessions, apiKeys, webhooks,
    });
  });

  // DELETE /api/privacy/memory — 清除长期记忆（软删除）
  app.delete("/api/privacy/memory", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = request.userId!;
    const result = await db.memory.updateMany({
      where: { userId, deletedAt: null },
      data: { deletedAt: new Date() },
    });
    sendOk(reply, { cleared: result.count });
  });

  // 兼容旧路径
  app.delete("/api/privacy/memories", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = request.userId!;
    const result = await db.memory.updateMany({
      where: { userId, deletedAt: null },
      data: { deletedAt: new Date() },
    });
    sendOk(reply, { cleared: result.count });
  });

  // DELETE /api/privacy/account — 删除账号（级联删除所有数据）
  app.delete("/api/privacy/account", { preHandler: [app.authGuard] }, async (request, reply) => {
    const userId = request.userId!;

    await db.$transaction([
      db.webhookDelivery.deleteMany({ where: { webhook: { userId } } }),
      db.webhook.deleteMany({ where: { userId } }),
      db.apiKey.deleteMany({ where: { userId } }),
      db.notification.deleteMany({ where: { userId } }),
      db.notificationPreference.deleteMany({ where: { userId } }),
      db.userSession.deleteMany({ where: { userId } }),
      db.companion.deleteMany({ where: { userId } }),
      db.memory.deleteMany({ where: { userId } }),
      db.plan.deleteMany({ where: { userId } }),
      db.userProfile.deleteMany({ where: { userId } }),
      db.userPermission.deleteMany({ where: { userId } }),
      db.refreshToken.deleteMany({ where: { userId } }),
      db.user.delete({ where: { id: userId } }),
    ]);

    sendNoContent(reply);
  });
}

import type { FastifyInstance } from "fastify";
import type { PrismaClient } from "../../generated/prisma/client.js";
import { z } from "zod";
import {
  sendOk,
  sendCreated,
  sendNoContent,
  sendError,
} from "../common/response.js";
import { NotFoundError, UnauthorizedError } from "../common/errors.js";
import * as mem from "../services/memoryStore.js";

// ─── Helpers ────────────────────────────────────────────────────────

function uid(request: { userId?: string }): string {
  const id = request.userId;
  if (!id) throw new UnauthorizedError("未登录");
  return id;
}

function parseJsonObject(val: unknown): Record<string, unknown> {
  if (typeof val === "string") {
    try { return JSON.parse(val) as Record<string, unknown>; } catch { return {}; }
  }
  return (val && typeof val === "object") ? val as Record<string, unknown> : {};
}

function parseJsonArray(val: unknown): string[] {
  if (Array.isArray(val)) return val as string[];
  if (typeof val === "string") {
    try { return JSON.parse(val) as string[]; } catch { return []; }
  }
  return [];
}

// ─── Profile Formatting ─────────────────────────────────────────────

function formatProfile(profile: Record<string, unknown>, user?: { displayName?: string | null }) {
  return {
    displayName: user?.displayName ?? null,
    city: (profile.city as string) ?? "杭州",
    startPoint: (profile.startPoint as string) ?? "浙大紫金港",
    secondaryStartPoints: parseJsonArray(profile.secondaryStartPoints),
    favoriteAreas: parseJsonArray(profile.favoriteAreas),
    defaultTimeWindow: (profile.defaultTimeWindow as string) ?? "下午14:00-18:00",
    transportMode: (profile.transportMode as string) ?? "any",
    distanceLimitKm: (profile.distanceLimitKm as number) ?? 10,
    walkingTolerance: (profile.walkingTolerance as string) ?? "moderate",
    queueTolerance: (profile.queueTolerance as string) ?? "normal",
    pace: (profile.pace as string) ?? "balanced",
    indoorPreference: (profile.indoorPreference as string) ?? "mixed",
    budgetMin: (profile.budgetMin as number) ?? 0,
    budgetMax: (profile.budgetMax as number) ?? 500,
    dietPreference: parseJsonArray(profile.dietPreference),
    avoidFoods: parseJsonArray(profile.avoidFoods),
    healthGoal: (profile.healthGoal as string) ?? "none",
    dinnerTimePreference: (profile.dinnerTimePreference as string) ?? "18:00-20:00",
    activityTags: parseJsonArray(profile.activityTags),
    avoidActivityTags: parseJsonArray(profile.avoidActivityTags),
    riskPreference: (profile.riskPreference as string) ?? "中性",
    personaCompleteness: (profile.personaCompleteness as number) ?? 0,
  };
}

// ─── Persona Completeness Calculation ───────────────────────────────

function calcPersonaCompleteness(profile: Record<string, unknown>): number {
  let score = 0;
  const checks: [string, (v: unknown) => boolean][] = [
    ["city", (v) => typeof v === "string" && v.length > 0],
    ["startPoint", (v) => typeof v === "string" && v.length > 0],
    ["defaultTimeWindow", (v) => typeof v === "string" && v.length > 0],
    ["transportMode", (v) => typeof v === "string" && v !== "any"],
    ["walkingTolerance", (v) => typeof v === "string" && v.length > 0],
    ["queueTolerance", (v) => typeof v === "string" && v.length > 0],
    ["pace", (v) => typeof v === "string" && v.length > 0],
    ["budgetMax", (v) => typeof v === "number" && v > 0],
    ["dietPreference", (v) => Array.isArray(v) && v.length > 0],
    ["activityTags", (v) => Array.isArray(v) && v.length > 0],
    ["riskPreference", (v) => typeof v === "string" && v.length > 0],
    ["favoriteAreas", (v) => Array.isArray(v) && v.length > 0],
  ];
  for (const [key, check] of checks) {
    if (check(profile[key])) score += Math.floor(100 / checks.length);
  }
  return Math.min(score, 100);
}

// ─── Seed Notifications ─────────────────────────────────────────────

async function seedNotifications(db: PrismaClient, userId: string) {
  const existing = await db.notification.count({ where: { userId } });
  if (existing > 0) return;

  await db.notification.createMany({
    data: [
      {
        userId,
        type: "welcome",
        title: "欢迎使用周末有谱",
        message: "描述你的想法，AI 会为你生成定制方案。",
        read: false,
      },
      {
        userId,
        type: "tip",
        title: "试试 AI 规划",
        message: "完善你的个人画像，获得更精准的推荐。",
        read: false,
      },
      {
        userId,
        type: "system",
        title: "隐私设置提醒",
        message: "你可以在个人中心管理数据权限和隐私选项。",
        read: false,
      },
    ],
  });
}

// ─── Notification Preferences ───────────────────────────────────────

async function ensureNotificationPrefs(db: PrismaClient, userId: string) {
  return db.notificationPreference.upsert({
    where: { userId },
    create: { userId },
    update: {},
  });
}

// ────────────────────────────────────────────────────────────────────
// Route Plugin
// ────────────────────────────────────────────────────────────────────

export async function registerProfileRoutes(app: FastifyInstance) {
  const db: PrismaClient | null = app.db;

  // ── 内存 fallback 模式 ──
  if (!db) {
    app.log.info("📝 Profile routes using in-memory store (no PostgreSQL)");

    // GET /api/profile/me
    app.get("/api/profile/me", { preHandler: [app.authGuard] }, async (request, reply) => {
      const userId = uid(request);
      const profile = mem.getFullProfile(userId);
      if (!profile) return sendError(reply, 404, "USER_NOT_FOUND", "用户不存在");
      sendOk(reply, {
        user: { id: profile.id, email: profile.email, displayName: profile.displayName, mode: profile.mode, role: profile.role, createdAt: profile.createdAt },
        profile: {
          displayName: profile.displayName,
          city: profile.city,
          startPoint: profile.startPoint,
          secondaryStartPoints: [],
          favoriteAreas: [],
          defaultTimeWindow: "下午14:00-18:00",
          transportMode: "any",
          distanceLimitKm: 10,
          walkingTolerance: "moderate",
          queueTolerance: "normal",
          pace: "balanced",
          indoorPreference: "mixed",
          budgetMin: profile.budgetMin,
          budgetMax: profile.budgetMax,
          dietPreference: [],
          avoidFoods: [],
          healthGoal: "none",
          dinnerTimePreference: "18:00-20:00",
          activityTags: [],
          avoidActivityTags: [],
          riskPreference: "中性",
          personaCompleteness: 20,
        },
        permissions: profile.permissions,
        stats: { planCount: 0, memoryCount: 0, favoriteCount: 0, unreadNotifications: 0, personaCompleteness: 20 },
      });
    });

    // PATCH /api/profile/me
    app.patch("/api/profile/me", { preHandler: [app.authGuard] }, async (request, reply) => {
      const userId = uid(request);
      const body = z.object({ displayName: z.string().max(50).optional(), city: z.string().max(50).optional(), startPoint: z.string().max(200).optional() }).parse(request.body);
      if (body.city || body.startPoint) {
        mem.upsertProfile(userId, { city: body.city, startPoint: body.startPoint });
      }
      const profile = mem.getFullProfile(userId);
      sendOk(reply, { city: profile?.city ?? "北京", startPoint: profile?.startPoint ?? "家附近", budgetMin: profile?.budgetMin ?? 200, budgetMax: profile?.budgetMax ?? 300, personaCompleteness: 20 });
    });

    // GET /api/profile/me/persona
    app.get("/api/profile/me/persona", { preHandler: [app.authGuard] }, async (request, reply) => {
      const userId = uid(request);
      const profile = mem.getFullProfile(userId);
      if (!profile) return sendError(reply, 404, "PROFILE_NOT_FOUND", "用户画像不存在");
      sendOk(reply, { city: profile.city, startPoint: profile.startPoint, budgetMin: profile.budgetMin, budgetMax: profile.budgetMax, personaCompleteness: 20 });
    });

    // PATCH /api/profile/me/persona
    app.patch("/api/profile/me/persona", { preHandler: [app.authGuard] }, async (request, reply) => {
      const userId = uid(request);
      const body = z.record(z.string(), z.unknown()).parse(request.body);
      mem.upsertProfile(userId, body as any);
      const profile = mem.getFullProfile(userId);
      sendOk(reply, { city: profile?.city, startPoint: profile?.startPoint, budgetMin: profile?.budgetMin, budgetMax: profile?.budgetMax, personaCompleteness: 20 });
    });

    // GET /api/profile/me/permissions
    app.get("/api/profile/me/permissions", { preHandler: [app.authGuard] }, async (request, reply) => {
      const userId = uid(request);
      sendOk(reply, mem.getPermissions(userId));
    });

    // PATCH /api/profile/me/permissions
    app.patch("/api/profile/me/permissions", { preHandler: [app.authGuard] }, async (request, reply) => {
      const userId = uid(request);
      const body = z.record(z.string(), z.boolean()).parse(request.body);
      sendOk(reply, mem.upsertPermissions(userId, body));
    });

    // 其他路由返回空数据或 501
    const emptyArrayRoutes = ["/api/profile/me/companions", "/api/notifications", "/api/auth/sessions"];
    for (const route of emptyArrayRoutes) {
      app.get(route, { preHandler: [app.authGuard] }, async (_request, reply) => sendOk(reply, { items: [], total: 0, sessions: [] }));
    }

    app.get("/api/profile/me/insights", { preHandler: [app.authGuard] }, async (_request, reply) => sendOk(reply, { insights: [] }));
    app.get("/api/profile/me/history", { preHandler: [app.authGuard] }, async (_request, reply) => sendOk(reply, { items: [], total: 0 }));

    app.get("/api/notifications/preferences", { preHandler: [app.authGuard] }, async (request, reply) => {
      const userId = uid(request);
      sendOk(reply, mem.getNotificationPrefs(userId));
    });
    app.patch("/api/notifications/preferences", { preHandler: [app.authGuard] }, async (request, reply) => {
      const userId = uid(request);
      const body = z.record(z.string(), z.boolean()).parse(request.body);
      sendOk(reply, mem.upsertNotificationPrefs(userId, body));
    });

    return;
  }

  // Auth is handled per-route via app.authGuard and uid() helper
  // 添加认证 hook 到所有 profile/notifications/account 路由
  const authPrefixes = ["/api/profile/", "/api/notifications", "/api/auth/sessions", "/api/account", "/api/plans/"];
  app.addHook("onRequest", async (request, reply) => {
    const path = request.url.split("?")[0];
    if (authPrefixes.some((p) => path.startsWith(p))) {
      await app.authGuard(request, reply);
    }
  });

  // ──────────────────────────────────────────────────────────────────
  // 1. GET /api/profile/me – Get full profile bundle
  // ──────────────────────────────────────────────────────────────────
  app.get("/api/profile/me", async (request, reply) => {
    const userId = uid(request);

    const [user, profile, permissions] = await Promise.all([
      db.user.findUnique({
        where: { id: userId },
        select: { id: true, email: true, displayName: true, mode: true, role: true, createdAt: true },
      }),
      db.userProfile.findUnique({ where: { userId } }),
      db.userPermission.findUnique({ where: { userId } }),
    ]);

    if (!user) throw new NotFoundError("用户不存在", "USER_NOT_FOUND");

    // Seed notifications on first access
    await seedNotifications(db, userId);

    const [planCount, memoryCount, favoriteCount, unreadNotifications] = await Promise.all([
      db.plan.count({ where: { userId } }),
      db.memory.count({ where: { userId, deletedAt: null } }),
      // Favorite count – plan doesn't have favorite field in real schema, count non-draft plans
      db.plan.count({ where: { userId, status: { not: "draft" } } }),
      db.notification.count({ where: { userId, read: false } }),
    ]);

    // Upsert profile if missing
    const safeProfile = profile ?? await db.userProfile.create({ data: { userId } });
    const safePerms = permissions ?? await db.userPermission.create({ data: { userId } });

    sendOk(reply, {
      user,
      profile: formatProfile(safeProfile, user),
      permissions: {
        locationEnabled: safePerms.locationEnabled,
        memoryEnabled: safePerms.memoryEnabled,
        calendarEnabled: safePerms.calendarEnabled,
        shareEnabled: safePerms.shareEnabled,
        developerEnabled: safePerms.developerEnabled,
      },
      stats: {
        planCount,
        memoryCount,
        favoriteCount,
        unreadNotifications,
        personaCompleteness: safeProfile.personaCompleteness,
      },
    });
  });

  // ──────────────────────────────────────────────────────────────────
  // 2. PATCH /api/profile/me – Update profile display info
  // ──────────────────────────────────────────────────────────────────
  app.patch("/api/profile/me", async (request, reply) => {
    const userId = uid(request);
    const body = z.object({
      displayName: z.string().max(50).optional(),
      city: z.string().max(50).optional(),
      startPoint: z.string().max(200).optional(),
    }).parse(request.body);

    // Update user displayName if provided
    if (body.displayName !== undefined) {
      await db.user.update({ where: { id: userId }, data: { displayName: body.displayName } });
    }

    // Update profile
    const profile = await db.userProfile.upsert({
      where: { userId },
      create: {
        userId,
        city: body.city ?? "杭州",
        startPoint: body.startPoint ?? "浙大紫金港",
      },
      update: {
        ...(body.city !== undefined && { city: body.city }),
        ...(body.startPoint !== undefined && { startPoint: body.startPoint }),
      },
    });

    // Recalculate persona completeness
    const completeness = calcPersonaCompleteness(profile as unknown as Record<string, unknown>);
    await db.userProfile.update({ where: { userId }, data: { personaCompleteness: completeness } });

    const user = await db.user.findUnique({ where: { id: userId }, select: { displayName: true } });
    sendOk(reply, formatProfile({ ...profile, personaCompleteness: completeness }, user ?? undefined));
  });

  // ──────────────────────────────────────────────────────────────────
  // 3. GET /api/profile/me/persona – Get persona data
  // ──────────────────────────────────────────────────────────────────
  app.get("/api/profile/me/persona", async (request, reply) => {
    const userId = uid(request);
    const profile = await db.userProfile.findUnique({ where: { userId } });
    if (!profile) throw new NotFoundError("用户画像不存在", "PROFILE_NOT_FOUND");

    sendOk(reply, formatProfile(profile));
  });

  // ──────────────────────────────────────────────────────────────────
  // 4. PATCH /api/profile/me/persona – Update persona preferences
  // ──────────────────────────────────────────────────────────────────
  app.patch("/api/profile/me/persona", async (request, reply) => {
    const userId = uid(request);
    const body = z.object({
      city: z.string().optional(),
      startPoint: z.string().optional(),
      secondaryStartPoints: z.array(z.string()).optional(),
      favoriteAreas: z.array(z.string()).optional(),
      defaultTimeWindow: z.string().optional(),
      transportMode: z.string().optional(),
      distanceLimitKm: z.number().optional(),
      walkingTolerance: z.string().optional(),
      queueTolerance: z.string().optional(),
      pace: z.string().optional(),
      indoorPreference: z.string().optional(),
      budgetMin: z.number().int().optional(),
      budgetMax: z.number().int().optional(),
      dietPreference: z.array(z.string()).optional(),
      avoidFoods: z.array(z.string()).optional(),
      healthGoal: z.string().optional(),
      dinnerTimePreference: z.string().optional(),
      activityTags: z.array(z.string()).optional(),
      avoidActivityTags: z.array(z.string()).optional(),
      riskPreference: z.string().optional(),
    }).parse(request.body);

    const data: Record<string, unknown> = {};
    for (const [key, val] of Object.entries(body)) {
      if (val === undefined) continue;
      if (Array.isArray(val)) {
        data[key] = JSON.stringify(val);
      } else {
        data[key] = val;
      }
    }

    const profile = await db.userProfile.upsert({
      where: { userId },
      create: { userId, ...data },
      update: data,
    });

    // Recalculate persona completeness
    const completeness = calcPersonaCompleteness(profile as unknown as Record<string, unknown>);
    await db.userProfile.update({ where: { userId }, data: { personaCompleteness: completeness } });

    sendOk(reply, formatProfile({ ...profile, personaCompleteness: completeness }));
  });

  // ──────────────────────────────────────────────────────────────────
  // 5. GET /api/profile/me/companions – List companions
  // ──────────────────────────────────────────────────────────────────
  app.get("/api/profile/me/companions", async (request, reply) => {
    const userId = uid(request);
    const companions = await db.companion.findMany({
      where: { userId },
      orderBy: { createdAt: "desc" },
    });

    sendOk(reply, companions.map((c) => ({
      ...c,
      preferences: parseJsonArray(c.preferences),
      avoid: parseJsonArray(c.avoid),
      diet: typeof c.diet === "string" ? c.diet : c.diet,
    })));
  });

  // ──────────────────────────────────────────────────────────────────
  // 6. POST /api/profile/me/companions – Create companion
  // ──────────────────────────────────────────────────────────────────
  app.post("/api/profile/me/companions", async (request, reply) => {
    const userId = uid(request);
    const body = z.object({
      type: z.string().default("person"),
      name: z.string().min(1).max(50),
      relation: z.string().default(""),
      ageGroup: z.string().default("adult"),
      preferences: z.array(z.string()).default([]),
      avoid: z.array(z.string()).default([]),
      mobility: z.string().default("normal"),
      diet: z.string().default(""),
      notes: z.string().default(""),
      isDefault: z.boolean().default(false),
    }).parse(request.body);

    const companion = await db.companion.create({
      data: {
        userId,
        type: body.type,
        name: body.name,
        relation: body.relation,
        ageGroup: body.ageGroup,
        preferences: JSON.stringify(body.preferences),
        avoid: JSON.stringify(body.avoid),
        mobility: body.mobility,
        diet: body.diet,
        notes: body.notes,
        isDefault: body.isDefault,
      },
    });

    sendCreated(reply, {
      ...companion,
      preferences: parseJsonArray(companion.preferences),
      avoid: parseJsonArray(companion.avoid),
    });
  });

  // ──────────────────────────────────────────────────────────────────
  // 7. PATCH /api/profile/me/companions/:id – Update companion
  // ──────────────────────────────────────────────────────────────────
  app.patch("/api/profile/me/companions/:id", async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);
    const body = z.object({
      type: z.string().optional(),
      name: z.string().min(1).max(50).optional(),
      relation: z.string().optional(),
      ageGroup: z.string().optional(),
      preferences: z.array(z.string()).optional(),
      avoid: z.array(z.string()).optional(),
      mobility: z.string().optional(),
      diet: z.string().optional(),
      notes: z.string().optional(),
      isDefault: z.boolean().optional(),
    }).parse(request.body);

    // Verify ownership
    const existing = await db.companion.findFirst({ where: { id, userId } });
    if (!existing) throw new NotFoundError("同伴不存在", "COMPANION_NOT_FOUND");

    const data: Record<string, unknown> = {};
    for (const [key, val] of Object.entries(body)) {
      if (val === undefined) continue;
      if (Array.isArray(val)) {
        data[key] = JSON.stringify(val);
      } else {
        data[key] = val;
      }
    }

    const companion = await db.companion.update({ where: { id }, data });
    sendOk(reply, {
      ...companion,
      preferences: parseJsonArray(companion.preferences),
      avoid: parseJsonArray(companion.avoid),
    });
  });

  // ──────────────────────────────────────────────────────────────────
  // 8. DELETE /api/profile/me/companions/:id – Delete companion
  // ──────────────────────────────────────────────────────────────────
  app.delete("/api/profile/me/companions/:id", async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);

    const existing = await db.companion.findFirst({ where: { id, userId } });
    if (!existing) throw new NotFoundError("同伴不存在", "COMPANION_NOT_FOUND");

    await db.companion.delete({ where: { id } });
    sendNoContent(reply);
  });

  // ──────────────────────────────────────────────────────────────────
  // 9. GET /api/profile/me/insights – Get AI insights (mock)
  // ──────────────────────────────────────────────────────────────────
  app.get("/api/profile/me/insights", async (request, reply) => {
    const userId = uid(request);

    const [profile, memories, planCount] = await Promise.all([
      db.userProfile.findUnique({ where: { userId } }),
      db.memory.findMany({ where: { userId, deletedAt: null }, orderBy: { weight: "desc" }, take: 10 }),
      db.plan.count({ where: { userId } }),
    ]);

    const topCategories = memories.reduce<Record<string, number>>((acc, m) => {
      acc[m.category] = (acc[m.category] || 0) + 1;
      return acc;
    }, {});
    const topCategory = Object.entries(topCategories).sort((a, b) => b[1] - a[1])[0]?.[0] ?? "general";

    const completeness = profile?.personaCompleteness ?? 0;

    const insights = [
      {
        id: "insight_activity",
        type: "recommendation",
        title: "活动偏好洞察",
        description: profile
          ? `你偏好 ${parseJsonArray(profile.activityTags).join("、") || "尚未设定"} 类型的活动。完善偏好可获得更精准推荐。`
          : "完善你的活动偏好，获得更精准的周末推荐。",
        icon: "sparkles",
      },
      {
        id: "insight_food",
        type: "recommendation",
        title: "饮食偏好分析",
        description: profile
          ? `你的饮食偏好为 ${parseJsonArray(profile.dietPreference).join("、") || "未设定"}，忌避 ${parseJsonArray(profile.avoidFoods).join("、") || "无"}。`
          : "告诉我们你的饮食偏好，帮你避开不合适的选择。",
        icon: "utensils",
      },
      {
        id: "insight_persona",
        type: "progress",
        title: "画像完成度",
        description: `你的个人画像已完成 ${completeness}%，${completeness >= 80 ? "非常完善" : "还有提升空间"}。`,
        icon: "user",
        progress: completeness,
      },
      {
        id: "insight_memory",
        type: "memory",
        title: "记忆洞察",
        description: memories.length > 0
          ? `你有 ${memories.length} 条长期记忆，最常关注「${topCategory}」领域。`
          : "开始规划周末，系统会自动记录你的偏好。",
        icon: "brain",
      },
      {
        id: "insight_plans",
        type: "stats",
        title: "规划统计",
        description: `你已生成 ${planCount} 个规划方案。${planCount > 5 ? "你是资深规划师！" : "继续探索更多可能性吧。"}`,
        icon: "bar-chart",
      },
    ];

    sendOk(reply, { insights });
  });

  // ──────────────────────────────────────────────────────────────────
  // 10. GET /api/profile/me/history – Get plan history
  // ──────────────────────────────────────────────────────────────────
  app.get("/api/profile/me/history", async (request, reply) => {
    const userId = uid(request);
    const query = z.object({
      page: z.coerce.number().int().min(1).default(1),
      pageSize: z.coerce.number().int().min(1).max(100).default(20),
    }).parse(request.query);

    const skip = (query.page - 1) * query.pageSize;

    const [items, total] = await Promise.all([
      db.plan.findMany({
        where: { userId },
        orderBy: { createdAt: "desc" },
        skip,
        take: query.pageSize,
        select: {
          id: true,
          title: true,
          summary: true,
          status: true,
          createdAt: true,
        },
      }),
      db.plan.count({ where: { userId } }),
    ]);

    sendOk(reply, { items, total });
  });

  // ──────────────────────────────────────────────────────────────────
  // 11. POST /api/plans/:id/rating – Rate a plan
  // ──────────────────────────────────────────────────────────────────
  app.post("/api/plans/:id/rating", async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);
    const body = z.object({
      rating: z.number().int().min(1).max(5),
      favorite: z.boolean().optional(),
    }).parse(request.body);

    const plan = await db.plan.findFirst({ where: { id, userId } });
    if (!plan) throw new NotFoundError("规划不存在", "PLAN_NOT_FOUND");

    // Store rating in intent metadata (Plan model uses Json intent field)
    const intent = parseJsonObject(plan.intent);
    intent.rating = body.rating;
    if (body.favorite !== undefined) intent.favorite = body.favorite;

    const updated = await db.plan.update({
      where: { id },
      data: { intent: JSON.stringify(intent) },
    });

    sendOk(reply, { id: updated.id, rating: body.rating, favorite: body.favorite ?? false });
  });

  // ──────────────────────────────────────────────────────────────────
  // 12. GET /api/notifications – List notifications
  // ──────────────────────────────────────────────────────────────────
  app.get("/api/notifications", async (request, reply) => {
    const userId = uid(request);

    // Seed notifications on first access
    await seedNotifications(db, userId);

    const query = z.object({
      page: z.coerce.number().int().min(1).default(1),
      pageSize: z.coerce.number().int().min(1).max(100).default(20),
    }).parse(request.query);

    const skip = (query.page - 1) * query.pageSize;

    const [items, total, unread] = await Promise.all([
      db.notification.findMany({
        where: { userId },
        orderBy: { createdAt: "desc" },
        skip,
        take: query.pageSize,
      }),
      db.notification.count({ where: { userId } }),
      db.notification.count({ where: { userId, read: false } }),
    ]);

    sendOk(reply, { items, total, unread });
  });

  // ──────────────────────────────────────────────────────────────────
  // 13. PATCH /api/notifications/:id/read – Mark notification read
  // ──────────────────────────────────────────────────────────────────
  app.patch("/api/notifications/:id/read", async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);

    const notification = await db.notification.findFirst({ where: { id, userId } });
    if (!notification) throw new NotFoundError("通知不存在", "NOTIFICATION_NOT_FOUND");

    const updated = await db.notification.update({
      where: { id },
      data: { read: true },
    });

    sendOk(reply, updated);
  });

  // ──────────────────────────────────────────────────────────────────
  // 14. DELETE /api/notifications/:id – Delete notification
  // ──────────────────────────────────────────────────────────────────
  app.delete("/api/notifications/:id", async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);

    const notification = await db.notification.findFirst({ where: { id, userId } });
    if (!notification) throw new NotFoundError("通知不存在", "NOTIFICATION_NOT_FOUND");

    await db.notification.delete({ where: { id } });
    sendNoContent(reply);
  });

  // ──────────────────────────────────────────────────────────────────
  // 15. GET /api/notifications/preferences – Get notification prefs
  // ──────────────────────────────────────────────────────────────────
  app.get("/api/notifications/preferences", async (request, reply) => {
    const userId = uid(request);
    const prefs = await ensureNotificationPrefs(db, userId);
    sendOk(reply, prefs);
  });

  // ──────────────────────────────────────────────────────────────────
  // 16. PATCH /api/notifications/preferences – Update notification prefs
  // ──────────────────────────────────────────────────────────────────
  app.patch("/api/notifications/preferences", async (request, reply) => {
    const userId = uid(request);
    const body = z.object({
      departureReminder: z.boolean().optional(),
      reservationReminder: z.boolean().optional(),
      shareFeedback: z.boolean().optional(),
      weatherAlert: z.boolean().optional(),
      planExpiry: z.boolean().optional(),
      emailEnabled: z.boolean().optional(),
      browserEnabled: z.boolean().optional(),
      calendarEnabled: z.boolean().optional(),
    }).parse(request.body);

    const prefs = await db.notificationPreference.upsert({
      where: { userId },
      create: { userId, ...body },
      update: body,
    });

    sendOk(reply, prefs);
  });

  // ──────────────────────────────────────────────────────────────────
  // 17. GET /api/profile/me/permissions – Get permission settings
  // ──────────────────────────────────────────────────────────────────
  app.get("/api/profile/me/permissions", async (request, reply) => {
    const userId = uid(request);
    const perms = await db.userPermission.upsert({
      where: { userId },
      create: { userId },
      update: {},
    });

    sendOk(reply, {
      locationEnabled: perms.locationEnabled,
      memoryEnabled: perms.memoryEnabled,
      calendarEnabled: perms.calendarEnabled,
      shareEnabled: perms.shareEnabled,
      developerEnabled: perms.developerEnabled,
    });
  });

  // ──────────────────────────────────────────────────────────────────
  // 18. PATCH /api/profile/me/permissions – Update permissions
  // ──────────────────────────────────────────────────────────────────
  app.patch("/api/profile/me/permissions", async (request, reply) => {
    const userId = uid(request);
    const body = z.object({
      locationEnabled: z.boolean().optional(),
      memoryEnabled: z.boolean().optional(),
      calendarEnabled: z.boolean().optional(),
      shareEnabled: z.boolean().optional(),
      developerEnabled: z.boolean().optional(),
    }).parse(request.body);

    const perms = await db.userPermission.upsert({
      where: { userId },
      create: { userId, ...body },
      update: body,
    });

    sendOk(reply, {
      locationEnabled: perms.locationEnabled,
      memoryEnabled: perms.memoryEnabled,
      calendarEnabled: perms.calendarEnabled,
      shareEnabled: perms.shareEnabled,
      developerEnabled: perms.developerEnabled,
    });
  });

  // ──────────────────────────────────────────────────────────────────
  // 19. GET /api/auth/sessions – List user sessions
  // ──────────────────────────────────────────────────────────────────
  app.get("/api/auth/sessions", async (request, reply) => {
    const userId = uid(request);
    const sessions = await db.userSession.findMany({
      where: { userId, revokedAt: null },
      orderBy: { lastSeenAt: "desc" },
      select: {
        id: true,
        userAgent: true,
        ipAddress: true,
        createdAt: true,
        lastSeenAt: true,
      },
    });

    sendOk(reply, { sessions });
  });

  // ──────────────────────────────────────────────────────────────────
  // 20. DELETE /api/auth/sessions/:id – Revoke a session
  // ──────────────────────────────────────────────────────────────────
  app.delete("/api/auth/sessions/:id", async (request, reply) => {
    const userId = uid(request);
    const { id } = z.object({ id: z.string() }).parse(request.params);

    const session = await db.userSession.findFirst({ where: { id, userId, revokedAt: null } });
    if (!session) throw new NotFoundError("会话不存在", "SESSION_NOT_FOUND");

    await db.userSession.update({
      where: { id },
      data: { revokedAt: new Date() },
    });

    sendNoContent(reply);
  });

  // ──────────────────────────────────────────────────────────────────
  // 21. POST /api/notifications/read-all – Mark all notifications read
  // ──────────────────────────────────────────────────────────────────
  app.post("/api/notifications/read-all", async (request, reply) => {
    const userId = uid(request);

    await db.notification.updateMany({
      where: { userId, read: false },
      data: { read: true },
    });

    sendOk(reply, { success: true });
  });

  // ──────────────────────────────────────────────────────────────────
  // 22. PATCH /api/account – Update account info
  // ──────────────────────────────────────────────────────────────────
  app.patch("/api/account", async (request, reply) => {
    const userId = uid(request);
    const body = z.object({
      displayName: z.string().min(1).max(50).optional(),
    }).parse(request.body);

    const user = await db.user.update({
      where: { id: userId },
      data: { displayName: body.displayName },
      select: { id: true, email: true, displayName: true, mode: true, role: true, createdAt: true },
    });

    sendOk(reply, user);
  });
}

export default registerProfileRoutes;

import { z } from "zod";
import { zodToJsonSchema } from "zod-to-json-schema";
import { demoProfile, planOptions, trafficRoutes, weather } from "../data/mockData";
import type { AgentResult, PlanningRequest } from "../types";
import {
  getCurrentContext,
  searchLocalActivities,
  checkBookingStatus,
  toolDefinitions,
  type GetCurrentContextRequest,
  type SearchLocalActivitiesRequest,
  type CheckBookingStatusRequest,
} from "./tools";
import {
  finalResponseSchema,
  executionStepSchema,
  activityPlanSchema,
  safeValidateFinalResponse,
  type FinalResponse,
} from "./schemas";

// ============================================================================
// OpenAI Client Configuration
// ============================================================================

/**
 * OpenAI 客户端实例
 *
 * 配置说明：
 * - 如果使用 OpenAI API，设置 baseURL 为官方端点
 * - 如果使用兼容 OpenAI 协议的其他 LLM（如通义千问、GLM、本地 Ollama），
 *   需要修改 baseURL 为对应的 API 地址
 * - API Key 应通过环境变量 OPENAI_API_KEY 配置，不应硬编码
 */
const openaiApiKey = process.env.OPENAI_API_KEY ?? "demo_key_for_testing";
const openaiBaseUrl = process.env.OPENAI_BASE_URL ?? "https://api.openai.com/v1";
const defaultModel = process.env.LLM_MODEL ?? "gpt-4o";

/**
 * LLM 调用配置接口
 */
interface LlmConfig {
  /** 模型名称，默认使用环境变量 LLM_MODEL 或 "gpt-4o" */
  model?: string;
  /** 温度参数，控制输出随机性，0-2 之间，默认 0.7 */
  temperature?: number;
  /** 最大 token 数，默认 4096 */
  maxTokens?: number;
  /** 请求超时时间（毫秒），默认 120000（2 分钟） */
  timeout?: number;
}

/**
 * 默认 LLM 配置
 */
const defaultLlmConfig: Required<LlmConfig> = {
  model: defaultModel,
  temperature: 0.7,
  maxTokens: 4096,
  timeout: 120000,
};

// ============================================================================
// System Prompt
// ============================================================================

/**
 * Agent 系统提示词
 *
 * 该提示词定义了 Agent 的角色定位、行为规范和工具使用指南。
 * 大模型将根据此提示词扮演"美团本地生活规划专家"角色。
 */
const SYSTEM_PROMPT = `你是美团本地生活规划专家，专注于为用户提供精准、高效的本地生活规划服务。

## 核心角色

你是一个专业的行程规划助手，能够理解用户的生活习惯、健康偏好、家庭构成等个性化需求，
并结合实时环境数据（天气、交通、排队状况）生成可落地执行的行程方案。

## 行为准则

1. **以用户为中心**：始终将用户的实际需求和约束放在首位
2. **数据驱动决策**：在做任何推荐前，必须先调用工具获取真实的上下文数据
3. **严谨可执行**：输出的方案必须是可以直接落地执行的，包含具体的时间、地点和操作
4. **透明可解释**：每个安排决定都需要说明理由，确保用户理解

## 工具使用规范

你必须按以下顺序使用工具：

### 第一步：获取环境上下文
在任何规划之前，必须调用 \`getCurrentContext\` 获取用户所在位置或目的地的：
- 当前时间
- 天气预报
- 交通路况
- 综合建议

### 第二步：搜索候选地点
根据用户需求调用 \`searchLocalActivities\` 搜索符合条件的兴趣点：
- 关键词：餐厅、景点、娱乐、购物等
- 筛选条件：亲子、低步行、无需排队、室内等
- 返回结果包含每个地点的详细信息

### 第三步：验证预约状态
对于需要预约的地点，调用 \`checkBookingStatus\` 确认：
- 当前排队人数
- 预计等待时间
- 可预约时段
- 预约建议

### 第四步：生成规划方案
基于上述数据，按照 FinalResponse 的 JSON Schema 输出最终结果。

## 用户约束识别

用户可能明确或隐含以下约束：

| 约束类型 | 识别关键词 | 处理方式 |
|---------|-----------|---------|
| 时间约束 | "4小时内"、"下午3点出发"、"周末一天" | 方案总时长不超过限制 |
| 预算约束 | "500元以内"、"不要太贵" | 预估花费不超过预算 |
| 成员构成 | "带孩子"、"一家三口"、"朋友聚会" | 选择 kidFriendly 场所，控制节奏 |
| 健康偏好 | "减肥"、"清淡"、"减脂" | 餐厅选择低油低盐菜品 |
| 特殊需求 | "不要排队"、"要室内"、"少走路" | 严格应用筛选条件 |

## 输出格式要求

你的最终输出必须严格符合以下 JSON Schema（FinalResponse）：

\`\`\`json
{
  "plans": [
    {
      "planTitle": "方案主题名称（20字以内）",
      "totalDurationHours": "总时长，如 4.5h",
      "totalEstimatedCost": "预估花费，如 ￥420",
      "steps": [
        {
          "timeSlot": "时间段，如 14:00-15:30",
          "actionType": "动作类型：就餐/游玩/交通/休息/购物/接送",
          "poiId": "地点ID，必须来自工具返回结果",
          "poiName": "地点名称",
          "reasoning": "安排理由，必须体现用户画像考量",
          "requiredBooking": true/false
        }
      ]
    }
  ]
}
\`\`\`

## 重要约束

1. **poiId 必须来自工具返回**：禁止凭空编造地点 ID，所有 ID 必须来自 searchLocalActivities 的结果
2. **时间不能重叠**：steps 中的时间必须按顺序排列，不能有时间冲突
3. **reasoning 必须具体**：说明该安排如何满足用户的具体需求（如"孩子5岁"）
4. **方案必须有差异**：多个方案应在主题、节奏或预算上有明显区别

## 响应格式

在完成所有工具调用后，直接输出符合 FinalResponse Schema 的 JSON 对象。
不要输出任何额外的解释性文字，只输出纯 JSON。`;

/**
 * 将 Zod Schema 转换为 JSON Schema，用于 LLM 的 structured output
 */
const outputJsonSchema = zodToJsonSchema(finalResponseSchema as unknown as Parameters<typeof zodToJsonSchema>[0], "FinalResponse");

// ============================================================================
// Tool Execution Map
// ============================================================================

/**
 * 工具函数映射表
 *
 * 根据工具名称动态调用对应的工具函数
 */
const toolFunctionMap = {
  getCurrentContext: async (args: unknown) => {
    const parsed = z.object({ location: z.string() }).parse(args);
    return getCurrentContext({ location: parsed.location } as GetCurrentContextRequest);
  },
  searchLocalActivities: async (args: unknown) => {
    const parsed = z
      .object({
        query: z.string(),
        requirements: z.array(z.string()).optional(),
        radius: z.number().optional(),
        sortBy: z.enum(["distance", "rating", "popularity"]).optional(),
      })
      .parse(args);
    return searchLocalActivities({
      query: parsed.query,
      requirements: parsed.requirements,
      radius: parsed.radius,
      sortBy: parsed.sortBy,
    } as SearchLocalActivitiesRequest);
  },
  checkBookingStatus: async (args: unknown) => {
    const parsed = z.object({ poiId: z.string() }).parse(args);
    return checkBookingStatus({ poiId: parsed.poiId } as CheckBookingStatusRequest);
  },
} as const;

/**
 * 工具名称类型
 */
type ToolName = keyof typeof toolFunctionMap;

// ============================================================================
// LLM Interaction Functions
// ============================================================================

/**
 * 调用 OpenAI兼容 API 执行对话
 *
 * @param messages - 对话消息历史
 * @param config - LLM 配置
 * @returns API 响应文本
 *
 * @throws Error 当 API 调用失败时抛出错误
 */
async function callLlm(
  messages: Array<{ role: "system" | "user" | "assistant"; content: string }>,
  config: Required<LlmConfig>
): Promise<string> {
  // 构建 OpenAI 请求体
  const requestBody = {
    model: config.model,
    messages: messages.map((m) => ({ role: m.role, content: m.content })),
    temperature: config.temperature,
    max_tokens: config.maxTokens,
    // 强制结构化输出
    response_format: {
      type: "json_schema",
      json_schema: {
        name: "FinalResponse",
        schema: outputJsonSchema,
        strict: true,
      },
    },
  };

  try {
    // 调用 OpenAI 兼容 API
    // 注意：在生产环境中应使用 openai SDK 的官方客户端
    const response = await fetch(`${openaiBaseUrl}/chat/completions`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${openaiApiKey}`,
      },
      body: JSON.stringify(requestBody),
      signal: AbortSignal.timeout(config.timeout),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`LLM API 调用失败: ${response.status} ${response.statusText} - ${errorText}`);
    }

    const data = (await response.json()) as {
      choices?: Array<{ message?: { content?: string } }>;
    };

    // 提取 assistant 的回复内容
    const assistantMessage = data.choices?.[0]?.message?.content;
    if (!assistantMessage) {
      throw new Error("LLM 响应格式异常，未找到有效内容");
    }

    return assistantMessage;
  } catch (error) {
    if (error instanceof Error) {
      if (error.name === "TimeoutError") {
        throw new Error(`LLM 请求超时（${config.timeout}ms）`);
      }
      throw error;
    }
    throw new Error(`LLM 调用失败: ${String(error)}`);
  }
}

/**
 * 解析 LLM 的 Function Calling 请求并执行
 *
 * @param toolCall - LLM 返回的工具调用请求
 * @returns 工具执行结果
 *
 * @throws Error 当工具名称未知或执行失败时抛出错误
 */
async function executeToolCall(toolCall: { name: string; arguments: string }): Promise<unknown> {
  const { name, arguments: argsString } = toolCall;

  // 解析 JSON 参数
  let args: unknown;
  try {
    args = JSON.parse(argsString);
  } catch {
    throw new Error(`工具 ${name} 的参数格式错误，无法解析为 JSON`);
  }

  // 查找对应的工具函数
  const toolFunction = toolFunctionMap[name as ToolName];
  if (!toolFunction) {
    const availableTools = Object.keys(toolFunctionMap).join(", ");
    throw new Error(`未知工具: ${name}，可用工具: ${availableTools}`);
  }

  // 执行工具函数
  try {
    const result = await toolFunction(args);
    return result;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`工具 ${name} 执行失败: ${message}`);
  }
}

// ============================================================================
// Main Planning Agent
// ============================================================================

/**
 * 构建用户消息
 *
 * 将用户的请求和上下文信息格式化为发送给 LLM 的消息
 *
 * @param request - 用户的规划请求
 * @returns 格式化的用户消息
 */
function buildUserMessage(request: PlanningRequest): string {
  const constraints: string[] = [];

  // 城市
  const city = request.city ?? demoProfile.city;
  constraints.push(`城市: ${city}`);

  // 起点
  const startPoint = request.startPoint ?? demoProfile.startPoint;
  constraints.push(`起点: ${startPoint}`);

  // 同行人
  const companions = request.companions ?? "family";
  constraints.push(`同行人: ${companions}`);

  // 预算
  if (request.budget) {
    constraints.push(`预算上限: ${request.budget}元`);
  }

  // 出发时间
  if (request.departAt) {
    constraints.push(`出发时间: ${request.departAt}`);
  }

  // 同行人详情
  let memberDetails = "";
  if (companions === "family" || companions === "friends") {
    memberDetails = demoProfile.family.map((m) => `- ${m}`).join("\n");
    if (memberDetails) {
      memberDetails = `\n家庭成员:\n${memberDetails}`;
    }
  }

  // 用户偏好
  let preferenceDetails = "";
  if (demoProfile.preferences.length > 0) {
    preferenceDetails = `\n用户偏好:\n${demoProfile.preferences.map((p) => `- ${p}`).join("\n")}`;
  }

  return `## 用户需求

原始需求: ${request.prompt}

## 约束条件

${constraints.join("\n")}
${memberDetails}
${preferenceDetails}

## 任务

请根据上述需求和约束，执行以下步骤：

1. 调用 getCurrentContext 获取 ${startPoint} 的当前环境信息
2. 调用 searchLocalActivities 搜索符合用户需求的兴趣点
3. 对需要预约的地点调用 checkBookingStatus 确认状态
4. 综合所有信息，生成 1-3 套差异化的行程方案

## 输出要求

请严格按照 FinalResponse Schema 输出 JSON 结果，不要输出任何额外文字。`;
}

/**
 * 运行基于 LLM 的规划 Agent
 *
 * 这是新的核心规划函数，使用 OpenAI API 进行自然语言理解和规划生成。
 * 它会自主调用工具获取上下文数据，并生成符合 schema 的结构化输出。
 *
 * @param request - 用户的规划请求
 * @param config - LLM 配置（可选）
 * @returns 结构化的规划结果
 *
 * @throws Error 当 LLM 调用失败、工具执行失败或输出格式错误时抛出错误
 *
 * @example
 * const result = await runLlmPlanningAgent({
 *   prompt: "周六带孩子去西湖玩",
 *   companions: "family",
 *   budget: 500
 * });
 * console.log(result.plans);
 */
export async function runLlmPlanningAgent(
  request: PlanningRequest,
  config?: LlmConfig
): Promise<FinalResponse> {
  // 合并配置
  const llmConfig: Required<LlmConfig> = { ...defaultLlmConfig, ...config };

  // 构建消息历史
  const messages: Array<{ role: "system" | "user" | "assistant"; content: string }> = [
    { role: "system", content: SYSTEM_PROMPT },
    { role: "user", content: buildUserMessage(request) },
  ];

  // 追踪已使用的工具，避免重复调用
  const usedTools = new Set<string>();
  const maxToolCalls = 10; // 防止无限循环

  try {
    // 循环调用 LLM，处理 function calling
    for (let iteration = 0; iteration < maxToolCalls; iteration++) {
      // 调用 LLM
      const response = await callLlm(messages, llmConfig);

      // 将 LLM 的响应添加到消息历史
      messages.push({ role: "assistant", content: response });

      // 尝试解析为 JSON
      try {
        const parsed = JSON.parse(response);

        // 检查是否为最终结果（包含 plans 字段）
        if ("plans" in parsed) {
          // 验证输出格式
          const [ok, resultOrError] = safeValidateFinalResponse(parsed);

          if (ok) {
            return resultOrError;
          } else {
            // 输出不符合 schema，追加纠正消息
            messages.push({
              role: "user",
              content: `你刚才的输出不符合 FinalResponse Schema 的要求:\n${resultOrError}\n\n请重新生成，严格按照 Schema 格式输出 JSON。`,
            });
            continue;
          }
        }

        // 如果 LLM 返回了函数调用请求（兼容旧版格式）
        if ("tool_calls" in parsed && Array.isArray(parsed.tool_calls)) {
          // 执行所有工具调用
          const toolResults = await Promise.all(
            parsed.tool_calls.map(async (toolCall: { id?: string; function?: { name?: string; arguments?: string }; name?: string; arguments?: string }) => {
              const toolName = toolCall.function?.name ?? toolCall.name ?? "unknown";
              const argsString = toolCall.function?.arguments ?? toolCall.arguments ?? "{}";

              usedTools.add(toolName);

              // 执行工具
              const result = await executeToolCall({ name: toolName, arguments: argsString });

              // 返回工具结果，格式兼容 OpenAI function calling
              return {
                tool_call_id: toolCall.id,
                role: "tool" as const,
                name: toolName,
                content: JSON.stringify(result, null, 2),
              };
            })
          );

          // 将工具结果添加到消息历史
          messages.push({
            role: "assistant",
            content: JSON.stringify({ tool_calls: parsed.tool_calls }),
          });

          for (const toolResult of toolResults) {
            messages.push(toolResult as { role: "system" | "user" | "assistant"; content: string });
          }

          continue;
        }

        // 如果既不是最终结果也不是工具调用，继续循环
        // LLM 可能还在思考
      } catch (parseError) {
        // JSON 解析失败，可能是 LLM 还在思考过程
        // 追加提示让 LLM 完成规划
        messages.push({
          role: "user",
          content: "请继续完成规划。如果你已经收集到足够的信息，请直接输出符合 FinalResponse Schema 的 JSON 结果。",
        });
      }
    }

    // 达到最大迭代次数仍未得到有效结果
    throw new Error(`规划过程超过最大迭代次数（${maxToolCalls}），请检查工具调用或 LLM 响应`);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);

    // 记录错误日志
    console.error("[runLlmPlanningAgent] 错误:", message, {
      request: request.prompt,
      usedTools: Array.from(usedTools),
      messageCount: messages.length,
    });

    throw new Error(`规划失败: ${message}`);
  }
}

// ============================================================================
// Legacy Functions (保持向后兼容)
