export function createConversation(data: {
  userId?: string | null;
  guestId?: string | null;
  title?: string;
  city?: string;
  modelMode?: string;
}): MemoryConversation {
  const conv: MemoryConversation = {
    id: randomUUID(),
    userId: data.userId ?? null,
    guestId: data.guestId ?? null,
    title: data.title ?? "新规划",
    city: data.city ?? "北京",
    modelMode: data.modelMode ?? "flash",
    createdAt: new Date(),
    updatedAt: new Date(),
  };
  conversations.set(conv.id, conv);
  messages.set(conv.id, []);
  return conv;
}

export function getConversation(id: string): MemoryConversation | undefined {
  return conversations.get(id);
}

export function listConversations(opts: {
  userId?: string;
  guestId?: string;
  limit?: number;
}): MemoryConversation[] {
  const limit = opts.limit ?? 50;
  return Array.from(conversations.values())
    .filter((c) => {
      if (opts.userId && c.userId === opts.userId) return true;
      if (opts.guestId && c.guestId === opts.guestId) return true;
      return false;
    })
    .sort((a, b) => b.updatedAt.getTime() - a.updatedAt.getTime())
    .slice(0, limit);
}

export function updateConversationTitle(id: string, title: string): void {
  const conv = conversations.get(id);
  if (conv) {
    conv.title = title;
    conv.updatedAt = new Date();
  }
}

// ═══════════════════════════════════════════════════
// Messages
// ═══════════════════════════════════════════════════

export function addMessage(data: {
  conversationId: string;
  role: string;
  content: string;
  payloadJson?: any;
}): MemoryMessage {
  const msg: MemoryMessage = {
    id: randomUUID(),
    conversationId: data.conversationId,
    role: data.role,
    content: data.content,
    payloadJson: data.payloadJson ?? null,
    createdAt: new Date(),
  };
  const list = messages.get(data.conversationId) ?? [];
  list.push(msg);
  messages.set(data.conversationId, list);
  // Update conversation updatedAt
  const conv = conversations.get(data.conversationId);
  if (conv) conv.updatedAt = new Date();
  return msg;
}

export function listMessages(conversationId: string): MemoryMessage[] {
  return messages.get(conversationId) ?? [];
}

// ═══════════════════════════════════════════════════
// Plans (memory mode)
// ═══════════════════════════════════════════════════

export function createPlan(data: {
  userId: string;
  conversationId?: string;
  title: string;
  summary?: string;
  options?: any[];
  execActions?: MemoryExecAction[];
}): MemoryPlan {
  const plan: MemoryPlan = {
    id: randomUUID(),
    userId: data.userId,
    conversationId: data.conversationId ?? null,
    status: "completed",
    title: data.title,
    summary: data.summary ?? "",
    favorite: false,
    options: data.options ?? [],
    execActions: data.execActions ?? [],
    createdAt: new Date(),
    updatedAt: new Date(),
  };
  memPlans.set(plan.id, plan);
  return plan;
}

export function getPlan(id: string): MemoryPlan | undefined {
  return memPlans.get(id);
}

export function listPlans(opts: {
  userId?: string;
  conversationId?: string;
  favoritesOnly?: boolean;
  limit?: number;
}): MemoryPlan[] {
  const limit = opts.limit ?? 50;
  return Array.from(memPlans.values())
    .filter((p) => {
      if (opts.userId && p.userId !== opts.userId) return false;
      if (opts.conversationId && p.conversationId !== opts.conversationId) return false;
      if (opts.favoritesOnly && !p.favorite) return false;
      return true;
    })
    .sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime())
    .slice(0, limit);
}

export function togglePlanFavorite(id: string): boolean | null {
  const plan = memPlans.get(id);
  if (!plan) return null;
  plan.favorite = !plan.favorite;
  plan.updatedAt = new Date();
  return plan.favorite;
}

// ═══════════════════════════════════════════════════
// Execution Actions (memory mode)
// ═══════════════════════════════════════════════════

export function updateExecActionStatus(
  id: string,
  status: string,
): MemoryExecAction | null {
  for (const plan of memPlans.values()) {
    const action = plan.execActions.find((a) => a.id === id);
    if (action) {
      action.status = status;
      action.updatedAt = new Date();
      return action;
    }
  }
  return null;
}

export function getExecAction(id: string): MemoryExecAction | null {
  for (const plan of memPlans.values()) {
    const action = plan.execActions.find((a) => a.id === id);
    if (action) return action;
  }
  return null;
}

// ═══════════════════════════════════════════════════
// User Events
// ═══════════════════════════════════════════════════

export function trackEvent(data: {
  userId?: string | null;
  guestId?: string | null;
  conversationId?: string | null;
  eventName: string;
  eventPayloadJson?: any;
  page?: string;
  traceId?: string;
}): MemoryUserEvent {
  const evt: MemoryUserEvent = {
    id: randomUUID(),
    userId: data.userId ?? null,
    guestId: data.guestId ?? null,
    conversationId: data.conversationId ?? null,
    eventName: data.eventName,
    eventPayloadJson: data.eventPayloadJson ?? {},
    page: data.page ?? "",
    traceId: data.traceId ?? "",
    createdAt: new Date(),
  };
  userEvents.push(evt);
  // Cap at 5000 entries
  if (userEvents.length > 5000) userEvents.splice(0, userEvents.length - 5000);
  return evt;
}

// ═══════════════════════════════════════════════════
// Client Error Logs
// ═══════════════════════════════════════════════════

export function logClientError(data: {
  userId?: string | null;
  guestId?: string | null;
  traceId?: string;
  route?: string;
  message: string;
  stack?: string | null;
  payloadJson?: any;
}): MemoryErrorLog {
  const log: MemoryErrorLog = {
    id: randomUUID(),
    userId: data.userId ?? null,
    guestId: data.guestId ?? null,
    traceId: data.traceId ?? "",
    route: data.route ?? "",
    message: data.message,
    stack: data.stack ?? null,
    payloadJson: data.payloadJson ?? null,
    createdAt: new Date(),
  };
  errorLogs.push(log);
  if (errorLogs.length > 2000) errorLogs.splice(0, errorLogs.length - 2000);
  return log;
}

/**
 * Token 服务 — JWT 签发 + Refresh Token 管理
 */

import crypto from "node:crypto";
import {
  signAccessToken,
  signRefreshToken,
  verifyRefreshToken,
  type AccessTokenPayload,
} from "../common/crypto.js";
import type { UserRepository } from "../repositories/userRepository.js";

export interface TokenPair {
  accessToken: string;
  refreshToken: string;
}

function hashToken(token: string): string {
  return crypto.createHash("sha256").update(token).digest("hex");
}

export class TokenService {
  constructor(private userRepo: UserRepository) {}

  /**
   * 为已认证用户生成 token pair，refresh token 存入 DB
   */
  async issueTokenPair(
    userId: string,
    email: string,
    role: string,
    meta?: { userAgent?: string; ipAddress?: string },
  ): Promise<TokenPair> {
    const jti = crypto.randomUUID();

    const accessToken = signAccessToken({ sub: userId, email, role });
    const refreshToken = signRefreshToken({ sub: userId, jti });

    const refreshExpiresIn = process.env.JWT_REFRESH_EXPIRES_IN ?? "7d";
    const expiresAt = this.parseExpiresIn(refreshExpiresIn);

    await this.userRepo.createRefreshToken({
      userId,
      tokenHash: hashToken(refreshToken),
      expiresAt,
      userAgent: meta?.userAgent,
      ipAddress: meta?.ipAddress,
    });

    return { accessToken, refreshToken };
  }

  /**
   * 刷新 token：验证旧 refresh token，签发新 pair
   */
  async refreshTokens(oldRefreshToken: string, meta?: { userAgent?: string; ipAddress?: string }): Promise<TokenPair | null> {
    try {
      const payload = verifyRefreshToken(oldRefreshToken);
      const tokenHash = hashToken(oldRefreshToken);

      const stored = await this.userRepo.findRefreshToken(tokenHash);
      if (!stored) return null;

      // 吊销旧 token
      await this.userRepo.revokeRefreshToken(stored.id);

      // 查用户
      const user = await this.userRepo.findById(payload.sub);
      if (!user || user.status !== "active") return null;

      // 签发新 pair
      return this.issueTokenPair(user.id, user.email, user.role, meta);
    } catch {
      return null;
    }
  }

  /**
   * 登出：吊销当前 refresh token
   */
  async revokeRefreshToken(refreshToken: string): Promise<void> {
    const tokenHash = hashToken(refreshToken);
    const stored = await this.userRepo.findRefreshToken(tokenHash);
    if (stored) {
      await this.userRepo.revokeRefreshToken(stored.id);
    }
  }

  /**
   * 登出所有设备：吊销该用户所有 refresh token
   */
  async revokeAllTokens(userId: string): Promise<void> {
    await this.userRepo.revokeAllRefreshTokens(userId);
  }

  private parseExpiresIn(value: string): Date {
    const match = value.match(/^(\d+)(s|m|h|d)$/);
    if (!match) return new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
    const num = parseInt(match[1], 10);
    const unit = match[2];
    const multipliers: Record<string, number> = { s: 1000, m: 60_000, h: 3_600_000, d: 86_400_000 };
    return new Date(Date.now() + num * (multipliers[unit] ?? 86_400_000));
  }
}

import { demoProfile, pois, trafficRoutes, weather } from "../data/mockData";

// ============================================================================
// Type Definitions
// ============================================================================

/**
 * 天气状况枚举
 */
export type WeatherCondition = "sunny" | "cloudy" | "overcast" | "light_rain" | "rainy" | "stormy";

/**
 * 交通拥堵等级枚举
 */
export type TrafficLevel = "smooth" | "moderate" | "congested" | "blocked";

/**
 * POI 类型枚举
 */
export type PoiType = "restaurant" | "scenic_spot" | "shopping" | "entertainment" | "hotel" | "transit" | "other";

/**
 * 预约建议枚举
 */
export type BookingAdvice = "walk_in" | "recommended" | "suggest_alternative" | "not_available";

/**
 * 获取当前位置上下文请求参数
 */
export interface GetCurrentContextRequest {
  /** 位置名称，如 "西湖断桥"、"海底捞湖滨店"、用户起点 "浙大紫金港" 等 */
  location: string;
}

/**
 * 天气信息结构
 */
export interface WeatherInfo {
  /** 城市名称 */
  city: string;
  /** 观测日期，格式为 YYYY-MM-DD */
  date: string;
  /** 天气状况英文标识 */
  condition: WeatherCondition;
  /** 天气状况中文描述 */
  conditionDescription: string;
  /** 降雨概率，范围 0-100 */
  rainProbability: number;
  /** 温度范围，格式为 "最低温-最高温℃" */
  temperature: string;
  /** 湿度百分比 */
  humidity: number;
  /** 风速，单位 km/h */
  windSpeed: number;
  /** 空气质量指数，数值越小越好 */
  aqi: number;
  /** 空气质量描述 */
  aqiDescription: string;
}

/**
 * 交通路况结构
 */
export interface TrafficInfo {
  /** 起点位置名称 */
  startPoint: string;
  /** 终点位置名称 */
  endPoint: string;
  /** 拥堵等级 */
  level: TrafficLevel;
  /** 拥堵等级中文描述 */
  levelDescription: string;
  /** 预计通行时间，单位分钟 */
  duration: number;
  /** 距离，单位公里 */
  distance: number;
  /** 主要风险提示（如果有） */
  riskWarning?: string;
}

/**
 * 当前时间信息
 */
export interface TimeInfo {
  /** 当前时间，格式为 HH:mm:ss */
  currentTime: string;
  /** 当前日期，格式为 YYYY-MM-DD */
  currentDate: string;
  /** 星期几，中文表示 */
  weekday: string;
  /** 是否为节假日 */
  isHoliday: boolean;
  /** 节假日名称（如果是节假日） */
  holidayName?: string;
}

/**
 * 获取当前位置上下文响应结构
 */
export interface GetCurrentContextResponse {
  /** 位置名称 */
  location: string;
  /** 天气信息 */
  weather: WeatherInfo;
  /** 交通信息列表（从该位置出发到常见目的地的交通状况） */
  traffic: TrafficInfo[];
  /** 当前时间信息 */
  time: TimeInfo;
  /** 综合建议，基于天气和交通状况给出 */
  suggestion: string;
}

// ============================================================================
// Type Definitions - searchLocalActivities
// ============================================================================

/**
 * 搜索本地活动请求参数
 */
export interface SearchLocalActivitiesRequest {
  /** 搜索关键词，如 "餐厅"、"儿童乐园"、"西湖景点" 等 */
  query: string;
  /** 特定要求筛选列表，支持的筛选标签包括：
   * - "亲子"：适合亲子活动
   * - "无需排队"：当前排队人数少
   * - "低步行"：距离较近或交通便利
   * - "室内"：室内场所
   * - "室外"：室外场所
   * - "低价"：人均消费较低
   * - "高价"：人均消费较高
   * - "快速"：适合快速消费
   * - "休闲"：适合长时间停留
   */
  requirements?: string[];
  /** 搜索半径，单位米，默认 5000 */
  radius?: number;
  /** 排序方式，默认 "distance"
   * - "distance"：按距离排序
   * - "rating"：按评分排序
   * - "popularity"：按热度排序
   */
  sortBy?: "distance" | "rating" | "popularity";
}

/**
 * POI 兴趣点基础信息
 */
export interface LocalPoi {
  /** POI 唯一标识符 */
  id: string;
  /** POI 名称 */
  name: string;
  /** POI 类型 */
  type: PoiType;
  /** POI 类型中文描述 */
  typeDescription: string;
  /** 距离，单位米 */
  distance: number;
  /** 距离描述，如 "约 500m"、"约 2km" */
  distanceDescription: string;
  /** 步行时间，单位分钟 */
  walkingTime: number;
  /** 驾车时间，单位分钟 */
  drivingTime: number;
  /** 纬度 */
  latitude: number;
  /** 经度 */
  longitude: number;
  /** 地址 */
  address: string;
  /** 评分，范围 1-5 */
  rating: number;
  /** 评分人数 */
  ratingCount: number;
  /** 人均消费，单位元（如果是消费场所） */
  avgPrice?: number;
  /** 标签列表 */
  tags: string[];
  /** 是否适合亲子 */
  kidFriendly: boolean;
  /** 营业时间 */
  businessHours: string;
  /** 联系电话 */
  phone?: string;
  /** 封面图片 URL */
  coverImage?: string;
  /** 详细描述 */
  description?: string;
}

/**
 * 搜索本地活动响应结构
 */
export interface SearchLocalActivitiesResponse {
  /** 搜索关键词 */
  query: string;
  /** 应用的筛选条件 */
  requirements: string[];
  /** 搜索半径（米） */
  radius: number;
  /** 符合条件的 POI 总数 */
  totalCount: number;
  /** 返回的 POI 列表（最多返回 20 条） */
  items: LocalPoi[];
  /** 搜索耗时（毫秒） */
  latency: number;
  /** 当前时间戳 */
  timestamp: string;
}

