/**
 * 查询预约状态请求参数
 */
export interface CheckBookingStatusRequest {
  /** POI 唯一标识符，对应 searchLocalActivities 返回的 id 字段 */
  poiId: string;
}

/**
 * 排队信息结构
 */
export interface QueueInfo {
  /** 当前排队人数 */
  currentQueue: number;
  /** 预计等待时间，单位分钟 */
  estimatedWaitTime: number;
  /** 当前叫号 */
  currentNumber: number;
  /** 最近的可用号码（如果需要取号） */
  nextAvailableNumber?: number;
  /** 排队状态："none" 无需排队，"light" 人数较少，"moderate" 正常，"busy" 繁忙 */
  status: "none" | "light" | "moderate" | "busy";
  /** 排队状态中文描述 */
  statusDescription: string;
}

/**
 * 预约时段信息
 */
export interface TimeSlot {
  /** 时段标识符 */
  id: string;
  /** 时段名称，如 "11:00-12:00"、"晚餐" */
  name: string;
  /** 日期，格式为 YYYY-MM-DD */
  date: string;
  /** 是否可预约 */
  available: boolean;
  /** 剩余可预约数量 */
  remainingCount?: number;
  /** 建议预约时间（如果是推荐时段） */
  recommended?: boolean;
}

/**
 * 预约状态详情
 */
export interface BookingDetail {
  /** 是否需要预约 */
  reservationRequired: boolean;
  /** 是否支持线上预约 */
  onlineReservationSupported: boolean;
  /** 是否支持线下取号 */
  offlineQueueSupported: boolean;
  /** 当前排队信息 */
  queueInfo: QueueInfo;
  /** 可预约时段列表（如果有） */
  availableSlots?: TimeSlot[];
  /** 预约规则说明 */
  bookingRules?: string[];
  /** 取消政策 */
  cancellationPolicy?: string;
}

/**
 * 价格区间信息
 */
export interface PriceRange {
  /** 最低消费或起价，单位元 */
  minPrice: number;
  /** 最高消费（如果有） */
  maxPrice?: number;
  /** 价格说明 */
  description: string;
}

/**
 * 查询预约状态响应结构
 */
export interface CheckBookingStatusResponse {
  /** POI 标识符 */
  poiId: string;
  /** POI 名称 */
  poiName: string;
  /** POI 类型 */
  poiType: PoiType;
  /** 当前预约状态 */
  bookingDetail: BookingDetail;
  /** 价格区间 */
  priceRange: PriceRange;
  /** 预约建议
   * - "walk_in"：可直接前往，无需预约
   * - "recommended"：建议提前预约
   * - "suggest_alternative"：建议选择其他场所
   * - "not_available"：当日已约满
